  hint_two text
) on commit drop;

insert into _myp_mock_forward_stage
  (question_id, question_number, question_type, prompt, prompt_doc, explanation,
   points, difficulty, topic, subtopic, config, hint_one, hint_two)
select ('d4000000-0000-4000-8000' || lpad((100 + (x->>'n')::integer)::text, 12, '0'))::uuid,
       (x->>'n')::integer, x->>'t', x->>'p', x->'d', x->>'e',
       (x->>'m')::numeric, x->>'df', x->>'tp', x->>'st', x->'cfg', x->>'h1', x->>'h2'
  from jsonb_array_elements('[{"n":1,"t":"single_choice","p":"A hospital records each patient''s blood group. Which classification is correct?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A hospital records each patient''s blood group. Which classification is correct?"}]}]},"e":"Blood group is a label, not a number: it is qualitative (categorical) data. It cannot be ordered or averaged, which is why a bar chart is appropriate and a mean is not.","m":2,"df":"medium","tp":"classification of data","st":"qualitative versus quantitative","cfg":{"source":"myp-mock-myp4-mock","question_number":1,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Ask whether the values are labels or amounts. If you cannot sensibly average them, they are qualitative.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["Qualitative (categorical), and a bar chart is appropriate","Quantitative continuous, because blood is measured","Quantitative discrete, because there are four groups","Qualitative, and the mean blood group should be calculated"],"option_key":[1],"hints":[]},"marking":"","h1":"Ask whether the values are labels or amounts. If you cannot sensibly average them, they are qualitative.","h2":null},{"n":2,"t":"single_choice","p":"The salaries in a small company are $22 000, $24 000, $25 000, $26 000 and $180 000. Which statement best describes the effect of the $180 000 salary?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The salaries in a small company are "},{"type":"text","text":"$22 000, $"},{"type":"text","text":"24 000, "},{"type":"text","text":"$25 000, $"},{"type":"text","text":"26 000 and "},{"type":"text","text":"$180 000. Which statement best describes the effect of the $"},{"type":"text","text":"180 000 salary?"}]}]},"e":"The mean is 277 000 ÷ 5 = $55 400 while four of the five salaries are below $26 000, so the mean is pulled up by the outlier. The median ($25 000) is unaffected and describes a typical salary better.","m":3,"df":"medium","tp":"mean, mode and median","st":"outliers and choice of measure","cfg":{"source":"myp-mock-myp4-mock","question_number":2,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"An outlier moves the mean because the mean uses every value''s size; the median only uses position.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["It inflates the mean, so the median describes a typical salary better","It inflates the median more than the mean","It has no effect because it is a single value","It makes the mode the best measure of centre"],"option_key":[1],"hints":[]},"marking":"","h1":"An outlier moves the mean because the mean uses every value''s size; the median only uses position.","h2":null},{"n":3,"t":"single_choice","p":"A grouped frequency table has classes 0 ≤ x < 10, 10 ≤ x < 20, 20 ≤ x < 30 with frequencies 5, 9 and 6. Which midpoint must be used for the class 10 ≤ x < 20 when estimating the mean?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A grouped frequency table has classes 0 ≤ x < 10, 10 ≤ x < 20, 20 ≤ x < 30 with frequencies 5, 9 and 6. Which midpoint must be used for the class 10 ≤ x < 20 when estimating the mean?"}]}]},"e":"The midpoint of a class is the average of its boundaries: (10 + 20)/2 = 15. Using 10 or 20 would place every value in that class at a boundary, which systematically skews the estimate.","m":2,"df":"hard","tp":"grouped data","st":"class midpoints","cfg":{"source":"myp-mock-myp4-mock","question_number":3,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Midpoint = (lower boundary + upper boundary) ÷ 2, not one of the boundaries.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["15","10, the lower boundary","20, the upper boundary","9, the frequency"],"option_key":[1],"hints":[]},"marking":"","h1":"Midpoint = (lower boundary + upper boundary) ÷ 2, not one of the boundaries.","h2":null},{"n":4,"t":"single_choice","p":"A histogram has one class of width 5 with frequency 20 and an adjacent class of width 10 with frequency 20. The bar for the narrower class is drawn taller. By what factor?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A histogram has one class of width 5 with frequency 20 and an adjacent class of width 10 with frequency 20. The bar for the narrower class is drawn taller. By what factor?"}]}]},"e":"Frequency density is frequency ÷ width: 20/5 = 4 for the narrow class and 20/10 = 2 for the wide one, so the narrow bar is twice as tall. Equal frequencies do NOT give equal bar heights when widths differ.","m":3,"df":"hard","tp":"histograms","st":"frequency density with unequal widths","cfg":{"source":"myp-mock-myp4-mock","question_number":4,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"In a histogram, area — not height — represents frequency. Height = frequency ÷ class width.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["2","1 — equal frequencies must give equal bars","0.5","4"],"option_key":[1],"hints":[]},"marking":"","h1":"In a histogram, area — not height — represents frequency. Height = frequency ÷ class width.","h2":null},{"n":5,"t":"single_choice","p":"A cumulative frequency curve shows 40 students in total. Reading across at cumulative frequency 10 gives the value 23. What have you found?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A cumulative frequency curve shows 40 students in total. Reading across at cumulative frequency 10 gives the value 23. What have you found?"}]}]},"e":"The lower quartile is the value below which a quarter of the data lies: 40 ÷ 4 = 10, so the x-value at cumulative frequency 10 is Q1 = 23. The median would be read at 20 and Q3 at 30.","m":3,"df":"hard","tp":"cumulative frequency","st":"reading quartiles from a curve","cfg":{"source":"myp-mock-myp4-mock","question_number":5,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"On a cumulative frequency curve, read n/4, n/2 and 3n/4 on the vertical axis to find Q1, the median and Q3.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["The lower quartile, Q1 = 23","The median, 23","The upper quartile, Q3 = 23","The interquartile range, 23"],"option_key":[1],"hints":[]},"marking":"","h1":"On a cumulative frequency curve, read n/4, n/2 and 3n/4 on the vertical axis to find Q1, the median and Q3.","h2":null},{"n":6,"t":"single_choice","p":"Two classes sit the same test. Class A has mean 62 and standard deviation 4; Class B has mean 62 and standard deviation 11. Which statement is correct?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two classes sit the same test. Class A has mean 62 and standard deviation 4; Class B has mean 62 and standard deviation 11. Which statement is correct?"}]}]},"e":"A larger standard deviation means the values are more spread out around the same mean. Both classes average 62, but Class B''s marks are far more variable, so individual performances are less predictable.","m":3,"df":"hard","tp":"standard deviation","st":"interpreting standard deviation","cfg":{"source":"myp-mock-myp4-mock","question_number":6,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Standard deviation measures spread, not level. Equal means say nothing about consistency.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["Class B has more variable marks, so its results are less consistent","Class B has a higher average mark","The standard deviations show Class A has more outliers","The two classes performed identically because the means are equal"],"option_key":[1],"hints":[]},"marking":"","h1":"Standard deviation measures spread, not level. Equal means say nothing about consistency.","h2":null},{"n":7,"t":"single_choice","p":"A stem-and-leaf diagram has rows 3 | 2 4 6 and 4 | 1 1 1 5 with the key ''4 | 1 means 41''. What is the mode?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A stem-and-leaf diagram has rows 3 | 2 4 6 and 4 | 1 1 1 5 with the key ''4 | 1 means 41''. What is the mode?"}]}]},"e":"The leaf 1 appears three times on stem 4, giving the value 41 three times — more often than any other value. Reading the key correctly is essential: on stem 4 the leaf 1 is 41, not 1.","m":3,"df":"hard","tp":"stem-and-leaf diagrams","st":"reading a stem-and-leaf key","cfg":{"source":"myp-mock-myp4-mock","question_number":7,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Always read the key first. The stem supplies the tens and the leaf the units in this example.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["41","1","46 (the highest value on the first row)","There is no mode"],"option_key":[1],"hints":[]},"marking":"","h1":"Always read the key first. The stem supplies the tens and the leaf the units in this example.","h2":null},{"n":8,"t":"single_choice","p":"A box plot has minimum 12, Q1 18, median 25, Q3 31 and maximum 60. Which statement best explains the shape of the distribution?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A box plot has minimum 12, Q1 18, median 25, Q3 31 and maximum 60. Which statement best explains the shape of the distribution?"}]}]},"e":"The upper whisker runs from 31 to 60, which is much longer than the lower whisker (12 to 18), and the median is closer to Q1. That indicates positive skew: a tail of high values.","m":3,"df":"hard","tp":"five-number summary and box plots","st":"shape from a box plot","cfg":{"source":"myp-mock-myp4-mock","question_number":8,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Compare whisker lengths and the position of the median inside the box; that is the evidence for skew.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["It is positively skewed — the upper whisker is much longer","It is symmetrical because the median lies inside the box","It is negatively skewed because the minimum is small","The shape cannot be judged from a box plot"],"option_key":[1],"hints":[]},"marking":"","h1":"Compare whisker lengths and the position of the median inside the box; that is the evidence for skew.","h2":null},{"n":9,"t":"single_choice","p":"Eight students scored 3, 5, 5, 6, 7, 8, 9, 9 on a quiz. A ninth student scores 10. How does the median change?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Eight students scored 3, 5, 5, 6, 7, 8, 9, 9 on a quiz. A ninth student scores 10. How does the median change?"}]}]},"e":"With eight values the median is (6 + 7)/2 = 6.5. Adding a ninth value gives 3, 5, 5, 6, 7, 8, 9, 9, 10, whose median is the 5th value = 7. The mean rises by less than a mark, but the median moves to an actual data value.","m":3,"df":"medium","tp":"mean, mode and median","st":"effect of n on the median","cfg":{"source":"myp-mock-myp4-mock","question_number":9,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"For an even number of values the median is the mean of the two middle values; with an odd number it is a single value.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["It rises from 6.5 to 7","It stays at 6.5","It rises from 6.5 to 7.5","It falls because more values are added"],"option_key":[1],"hints":[]},"marking":"","h1":"For an even number of values the median is the mean of the two middle values; with an odd number it is a single value.","h2":null},{"n":10,"t":"single_choice","p":"A cumulative frequency table ends with a total frequency of 50. A candidate reads the median at cumulative frequency 50. What error have they made?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A cumulative frequency table ends with a total frequency of 50. A candidate reads the median at cumulative frequency 50. What error have they made?"}]}]},"e":"The median is read at n/2 = 25, not at the total. Cumulating to 50 locates the maximum, so the candidate has found the largest value rather than the middle one.","m":3,"df":"hard","tp":"cumulative frequency","st":"misreading a cumulative axis","cfg":{"source":"myp-mock-myp4-mock","question_number":10,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"The vertical axis of a cumulative frequency diagram runs to n, so quartiles are read at n/4, n/2 and 3n/4.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["They read the maximum instead of the median; the median is at 25","They should have read at 50 ÷ 4","Nothing — the median is always at the total","They should have subtracted 50 from the total"],"option_key":[1],"hints":[]},"marking":"","h1":"The vertical axis of a cumulative frequency diagram runs to n, so quartiles are read at n/4, n/2 and 3n/4.","h2":null},{"n":11,"t":"single_choice","p":"For the grouped table 0 ≤ x < 10, 10 ≤ x < 20, 20 ≤ x < 30 with frequencies 4, 7, 5, what is the estimated mean?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For the grouped table 0 ≤ x < 10, 10 ≤ x < 20, 20 ≤ x < 30 with frequencies 4, 7, 5, what is the estimated mean?"}]}]},"e":"Σf x = 4(5) + 7(15) + 5(25) = 20 + 105 + 125 = 250 and Σf = 16, so the estimated mean is 250 ÷ 16 = 15.625.","m":3,"df":"hard","tp":"grouped data","st":"estimated mean from midpoints","cfg":{"source":"myp-mock-myp4-mock","question_number":11,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Estimated mean = Σ(f × midpoint) ÷ Σf. Write both sums before dividing.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["15.625","15 (the middle class midpoint)","16 (Σf ÷ 1, a misread)","20 (the highest midpoint)"],"option_key":[1],"hints":[]},"marking":"","h1":"Estimated mean = Σ(f × midpoint) ÷ Σf. Write both sums before dividing.","h2":null},{"n":12,"t":"single_choice","p":"A histogram bar covers 20 ≤ x < 30 with height (frequency density) 1.4. What is the frequency of that class?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A histogram bar covers 20 ≤ x < 30 with height (frequency density) 1.4. What is the frequency of that class?"}]}]},"e":"Frequency = density × class width = 1.4 × 10 = 14. The area of the bar is the frequency, which is why density must be multiplied by the width.","m":3,"df":"hard","tp":"histograms","st":"frequency from density","cfg":{"source":"myp-mock-myp4-mock","question_number":12,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"frequency = frequency density × class width; equivalently, the area of each bar.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["14","1.4","28","140"],"option_key":[1],"hints":[]},"marking":"","h1":"frequency = frequency density × class width; equivalently, the area of each bar.","h2":null},{"n":13,"t":"single_choice","p":"A data set is 4, 4, 4, 4, 4. What is its standard deviation, and what does that tell you?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data set is 4, 4, 4, 4, 4. What is its standard deviation, and what does that tell you?"}]}]},"e":"Every value equals the mean 4, so each deviation is 0, Σ(x − x̄)² = 0 and σ = 0. A standard deviation of zero means there is no spread at all.","m":2,"df":"hard","tp":"standard deviation","st":"standard deviation of a constant set","cfg":{"source":"myp-mock-myp4-mock","question_number":13,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Standard deviation is the root mean square deviation; if there are no deviations, it is zero.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["0 — there is no spread","4 — the mean is 4","2 — half the mean","It cannot be calculated from five values"],"option_key":[1],"hints":[]},"marking":"","h1":"Standard deviation is the root mean square deviation; if there are no deviations, it is zero.","h2":null},{"n":14,"t":"single_choice","p":"Two runners'' times (minutes) over 6 races: A: 30, 32, 33, 34, 36, 37. B: 28, 31, 33, 33, 35, 44. Which comparison is supported by the data?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two runners'' times (minutes) over 6 races: A: 30, 32, 33, 34, 36, 37. B: 28, 31, 33, 33, 35, 44. Which comparison is supported by the data?"}]}]},"e":"Both have the same mean (202 ÷ 6 ≈ 33.67) and the same median (33), but B has a much larger spread (range 16 against 7, and larger deviations), so B is less consistent even though the averages match.","m":3,"df":"hard","tp":"comparing data sets","st":"comparing centre and spread","cfg":{"source":"myp-mock-myp4-mock","question_number":14,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Compare a measure of centre AND a measure of spread; two distributions can share a centre and differ in consistency.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["The medians are equal but B is less consistent","B has the higher median","A has the larger range","A is less consistent because its values are closer together"],"option_key":[1],"hints":[]},"marking":"","h1":"Compare a measure of centre AND a measure of spread; two distributions can share a centre and differ in consistency.","h2":null},{"n":15,"t":"single_choice","p":"A line graph of a shop''s monthly sales rises steeply from January to March, then is flat from March to August. Which conclusion is justified?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A line graph of a shop''s monthly sales rises steeply from January to March, then is flat from March to August. Which conclusion is justified?"}]}]},"e":"The graph supports a statement about the trend in the recorded months only: sales grew early in the year and then held steady. It does not explain why, and it says nothing about September onwards.","m":3,"df":"hard","tp":"line graphs","st":"trend versus cause","cfg":{"source":"myp-mock-myp4-mock","question_number":15,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"A graph shows what happened in the data, not why. Keep causal claims out of a data interpretation.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["Sales increased early in the year and then stayed roughly constant","The shop will close because sales stopped growing","The shop''s advertising caused the March increase","Sales were highest in August"],"option_key":[1],"hints":[]},"marking":"","h1":"A graph shows what happened in the data, not why. Keep causal claims out of a data interpretation.","h2":null},{"n":16,"t":"single_choice","p":"A market researcher records four variables. Which one of them is continuous data?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A market researcher records four variables. Which one of them is continuous data?"}]}]},"e":"The mass of a parcel can take any value in an interval, so it is continuous. Shoe size, the number of siblings and a house number are counts or labels.","m":3,"df":"hard","tp":"classification of data","st":"discrete versus continuous","cfg":{"source":"myp-mock-myp4-mock","question_number":16,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"If the value can, in principle, be measured more and more precisely, it is continuous; if you count it, it is discrete.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["The mass of a parcel, measured to the nearest gram","A shoe size","The number of siblings a student has","A house number"],"option_key":[1],"hints":[]},"marking":"","h1":"If the value can, in principle, be measured more and more precisely, it is continuous; if you count it, it is discrete.","h2":null},{"n":17,"t":"single_choice","p":"For the data 3, 5, 7, 8, 10, 12, 14, 15, 18 (using the median-excluded quartile method), what is the interquartile range?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For the data 3, 5, 7, 8, 10, 12, 14, 15, 18 (using the median-excluded quartile method), what is the interquartile range?"}]}]},"e":"There are 9 values, so the median is the 5th value = 10. The lower half is 3, 5, 7, 8 with Q1 = 6, and the upper half is 12, 14, 15, 18 with Q3 = 14.5. IQR = 14.5 − 6 = 8.5.","m":3,"df":"hard","tp":"five-number summary and box plots","st":"quartiles with an odd n","cfg":{"source":"myp-mock-myp4-mock","question_number":17,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Split the ordered data at the median and exclude the median itself when n is odd, then average the middle two of each half.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["8.5","10","15 (maximum − minimum)","5 (Q3 − median)"],"option_key":[1],"hints":[]},"marking":"","h1":"Split the ordered data at the median and exclude the median itself when n is odd, then average the middle two of each half.","h2":null},{"n":18,"t":"single_choice","p":"A grouped table has classes with widths 10, 10, 20 and 20 and frequencies 6, 9, 10 and 6. Which statement about drawing a histogram is correct?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A grouped table has classes with widths 10, 10, 20 and 20 and frequencies 6, 9, 10 and 6. Which statement about drawing a histogram is correct?"}]}]},"e":"Because the widths differ, the bar heights must be frequency densities: 0.6, 0.9, 0.5 and 0.3. Using the raw frequencies would make the 20-wide classes look twice as important as they are.","m":3,"df":"hard","tp":"grouped data","st":"density for mixed widths","cfg":{"source":"myp-mock-myp4-mock","question_number":18,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Divide each frequency by its own class width before drawing, so that all areas remain comparable.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["The four densities are 0.6, 0.9, 0.5 and 0.3","The bars should be 6, 9, 10 and 6 high","All four bars are the same height because the total is 31","The widths cannot be compared on a histogram"],"option_key":[1],"hints":[]},"marking":"","h1":"Divide each frequency by its own class width before drawing, so that all areas remain comparable.","h2":null},{"n":19,"t":"single_choice","p":"A data set has mean 20, median 22 and mode 30. Which statement is most consistent with these values?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data set has mean 20, median 22 and mode 30. Which statement is most consistent with these values?"}]}]},"e":"Mean < median < mode is the classic signature of a negatively (left) skewed distribution, where a few small values pull the mean down while the mode sits at the most frequent higher value.","m":3,"df":"hard","tp":"mean, mode and median","st":"mean, median and mode together","cfg":{"source":"myp-mock-myp4-mock","question_number":19,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Compare the order of mean, median and mode: a mean below the median suggests a low-value tail.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["The data are negatively skewed, with a tail of small values","The data are perfectly symmetrical","The data are positively skewed, with a tail of large values","The three measures cannot disagree"],"option_key":[1],"hints":[]},"marking":"","h1":"Compare the order of mean, median and mode: a mean below the median suggests a low-value tail.","h2":null},{"n":20,"t":"single_choice","p":"A survey asks students to choose one of five favourite sports. Which is the most suitable representation?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A survey asks students to choose one of five favourite sports. Which is the most suitable representation?"}]}]},"e":"The data are categorical with five named groups, so a bar chart (or a pie chart) compares the counts. A histogram and a cumulative frequency curve require numerical classes.","m":2,"df":"medium","tp":"classification of data","st":"choosing a representation","cfg":{"source":"myp-mock-myp4-mock","question_number":20,"paper_section":"A","myp_criterion":"A","strand":"","next_time_hint":"Histograms, cumulative curves and box plots need numerical data. Named categories use bar or pie charts.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["A bar chart, because the data are categorical","A histogram, because there are five groups","A cumulative frequency curve, because the counts add to the total","A box plot, because it shows the spread of sports"],"option_key":[1],"hints":[]},"marking":"","h1":"Histograms, cumulative curves and box plots need numerical data. Named categories use bar or pie charts.","h2":null},{"n":21,"t":"single_choice","p":"A line graph of a child''s height is plotted monthly for two years and shows a steep rise. Why is a line graph appropriate here but misleading if the axes do not start at zero?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A line graph of a child''s height is plotted monthly for two years and shows a steep rise. Why is a line graph appropriate here but misleading if the axes do not start at zero?"}]}]},"e":"A line graph shows a continuous change over time, which suits monthly height. If the vertical axis starts at, say, 140 cm instead of 0, small changes look dramatic, which exaggerates the trend.","m":3,"df":"hard","tp":"line graphs","st":"misleading axes","cfg":{"source":"myp-mock-myp4-mock","question_number":21,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"Check both axes before interpreting a line graph; a truncated vertical scale magnifies every fluctuation.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["It suits change over time, but a truncated vertical axis exaggerates small changes","It is inappropriate because height is continuous data","It is appropriate because height is a category","A pie chart would show the change better"],"option_key":[1],"hints":[]},"marking":"","h1":"Check both axes before interpreting a line graph; a truncated vertical scale magnifies every fluctuation.","h2":null},{"n":22,"t":"single_choice","p":"A data set of 5 values has Σ(x − x̄)² = 80. What is the population standard deviation?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data set of 5 values has Σ(x − x̄)² = 80. What is the population standard deviation?"}]}]},"e":"Variance = 80 ÷ 5 = 16, so σ = √16 = 4. Dividing by 5 (the number of values) is what distinguishes the population standard deviation from the sample version.","m":3,"df":"hard","tp":"standard deviation","st":"computing sigma from the sum of squares","cfg":{"source":"myp-mock-myp4-mock","question_number":22,"paper_section":"A","myp_criterion":"B","strand":"","next_time_hint":"σ = √(Σ(x − x̄)² / n). Divide by n first, then take the square root — not the other way round.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","option_labels":["4","16","8","80"],"option_key":[1],"hints":[]},"marking":"","h1":"σ = √(Σ(x − x̄)² / n). Divide by n first, then take the square root — not the other way round.","h2":null},{"n":23,"t":"assess_parts","p":"A hospital records, for each patient admitted in a week: age (years), blood group, number of previous admissions, and body temperature (°C).\n\n(a) Classify each of the four variables as qualitative or quantitative.\n(b) For the quantitative variables, state whether each is discrete or continuous.\n(c) Justify your classification of ''number of previous admissions''.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A hospital records, for each patient admitted in a week: age (years), blood group, number of previous admissions, and body temperature (°C)."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Classify each of the four variables as qualitative or quantitative.\n(b) For the quantitative variables, state whether each is discrete or continuous.\n(c) Justify your classification of ''number of previous admissions''."}]}]},"e":"Blood group is qualitative; age and temperature are quantitative continuous; the number of previous admissions is quantitative discrete because it is a count with gaps between permitted values.","m":5,"df":"hard","tp":"classification of data","st":"classification of data","cfg":{"source":"myp-mock-myp4-mock","question_number":23,"paper_section":"B","myp_criterion":"B","strand":"B(i)","next_time_hint":"Classify in two steps: is it a label or an amount, and if an amount, is it counted or measured?","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Name the qualitative variable.","kind":"text","points":1,"hints":["A qualitative variable is a label or category, not an amount.","Which of the four cannot sensibly be averaged?"],"strand":"B(i)","accepted":["blood group"]},{"id":"b","label":"(b)","prompt":"State which quantitative variable is discrete.","kind":"text","points":2,"hints":["A discrete variable is counted in whole steps.","Age and temperature can be measured more precisely; admissions cannot."],"strand":"B(ii)","accepted":["number of previous admissions"],"keywords":[["number"],["previous"],["admissions"]],"minKeywordGroups":3},{"id":"c","label":"(c)","prompt":"Justify why ''number of previous admissions'' must be discrete.","kind":"text","points":2,"hints":["Can a patient have 2.4 previous admissions?","The values jump from one whole number to the next."],"strand":"B(iii)","accepted":["you can only count whole admissions, so its values are separate whole numbers"],"keywords":[["count"],["whole"],["admissions"],["values"],["separate"],["numbers"]],"minKeywordGroups":4}],"marking":"(a) 1 mark for blood group. (b) 2 marks: 1 for admissions discrete, 1 for age/temperature continuous. (c) 2 marks: 1 for ''counted'', 1 for the consequence (no fractional values).","marking_criteria":"(a) 1 mark for blood group. (b) 2 marks: 1 for admissions discrete, 1 for age/temperature continuous. (c) 2 marks: 1 for ''counted'', 1 for the consequence (no fractional values).","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"In (c) explain the counting argument, not only the definition of discrete."},"marking":"(a) 1 mark for blood group. (b) 2 marks: 1 for admissions discrete, 1 for age/temperature continuous. (c) 2 marks: 1 for ''counted'', 1 for the consequence (no fractional values).","h1":"Classify in two steps: is it a label or an amount, and if an amount, is it counted or measured?","h2":"A qualitative variable is a label or category, not an amount."},{"n":24,"t":"assess_parts","p":"The masses of 40 parcels, in kilograms, are summarised below.\n\n10 ≤ m < 15: 6 parcels\n15 ≤ m < 20: 14 parcels\n20 ≤ m < 30: 12 parcels\n30 ≤ m < 40: 8 parcels\n\n(a) State the class width of the third class.\n(b) Calculate the estimated mean mass, using midpoints.\n(c) Explain why the class 20 ≤ m < 30 has a lower frequency density than 15 ≤ m < 20 even though it has almost the same frequency.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The masses of 40 parcels, in kilograms, are summarised below."}]},{"type":"paragraph","content":[{"type":"text","text":"10 ≤ m < 15: 6 parcels\n15 ≤ m < 20: 14 parcels\n20 ≤ m < 30: 12 parcels\n30 ≤ m < 40: 8 parcels"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the class width of the third class.\n(b) Calculate the estimated mean mass, using midpoints.\n(c) Explain why the class 20 ≤ m < 30 has a lower frequency density than 15 ≤ m < 20 even though it has almost the same frequency."}]}]},"e":"Σf x = 6(12.5) + 14(17.5) + 12(25) + 8(35) = 75 + 245 + 300 + 280 = 900, so the estimated mean is 900/40 = 22.5 kg. Densities are 1.2, 2.8, 1.2 and 0.8; the third class is less dense than the second because its frequency is spread over twice the width.","m":7,"df":"hard","tp":"grouped data","st":"grouped data","cfg":{"source":"myp-mock-myp4-mock","question_number":24,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Estimated mean = Σ(f × midpoint) ÷ Σf. Frequency density = frequency ÷ class width.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the class width of 20 ≤ m < 30.","kind":"numeric","points":1,"hints":["Width = upper boundary − lower boundary.","30 − 20."],"strand":"C(i)","answer":10,"tolerance":0,"unit":"kg"},{"id":"b","label":"(b)","prompt":"Calculate Σ(f × midpoint).","kind":"numeric","points":2,"hints":["Use the midpoint of each class: 12.5, 17.5, 25, 35.","Multiply each midpoint by its frequency and add the four products."],"strand":"C(ii)","answer":900,"tolerance":0,"unit":"kg"},{"id":"c","label":"(c)","prompt":"Calculate the estimated mean mass, in kilograms.","kind":"numeric","points":2,"hints":["Divide your Σ(f × midpoint) by the total frequency.","The frequencies add to 40."],"strand":"C(iii)","answer":22.5,"tolerance":0.01,"unit":"kg"},{"id":"d","label":"(d)","prompt":"Explain the lower frequency density of the third class.","kind":"text","points":2,"hints":["Frequency density = frequency ÷ class width.","Compare 12/10 with 14/5."],"strand":"C(iv)","accepted":["its class width is twice as large, so the same frequency is spread over a wider interval, giving a lower density: 1.2 against 2.8"],"keywords":[["class"],["width"],["twice"],["large"],["frequency"],["spread"]],"minKeywordGroups":4}],"marking":"(a) 1 mark for 10. (b) 2 marks: 1 for the four products, 1 for 900. (c) 2 marks: 1 for dividing by 40, 1 for 22.5. (d) 2 marks: 1 for the density formula, 1 for the comparison 1.2 vs 2.8.","marking_criteria":"(a) 1 mark for 10. (b) 2 marks: 1 for the four products, 1 for 900. (c) 2 marks: 1 for dividing by 40, 1 for 22.5. (d) 2 marks: 1 for the density formula, 1 for the comparison 1.2 vs 2.8.","response_tools":["rich_text","math","statistics"],"response_requirement":"text","response_guidance":"Build the grouped table in the statistics workspace as a check, but record your answers in the boxes.","statistics_chart":"histogram","response_stats":{"title":"Your statistics construction","instructions":"Build the grouped table in the statistics workspace as a check, but record your answers in the boxes.","chart":"histogram","starter":{"chart":"histogram"}}},"marking":"(a) 1 mark for 10. (b) 2 marks: 1 for the four products, 1 for 900. (c) 2 marks: 1 for dividing by 40, 1 for 22.5. (d) 2 marks: 1 for the density formula, 1 for the comparison 1.2 vs 2.8.","h1":"Estimated mean = Σ(f × midpoint) ÷ Σf. Frequency density = frequency ÷ class width.","h2":"Width = upper boundary − lower boundary."},{"n":25,"t":"assess_parts","p":"The waiting times, in minutes, of 15 patients are:\n\n4, 6, 7, 8, 9, 11, 12, 13, 15, 16, 18, 20, 23, 25, 28\n\n(a) State the median.\n(b) Calculate the lower and upper quartiles.\n(c) Calculate the interquartile range.\n(d) A waiting time of 45 minutes is recorded the next day. Explain, using the 1.5 × IQR rule, whether it is an outlier.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The waiting times, in minutes, of 15 patients are:"}]},{"type":"paragraph","content":[{"type":"text","text":"4, 6, 7, 8, 9, 11, 12, 13, 15, 16, 18, 20, 23, 25, 28"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the median.\n(b) Calculate the lower and upper quartiles.\n(c) Calculate the interquartile range.\n(d) A waiting time of 45 minutes is recorded the next day. Explain, using the 1.5 × IQR rule, whether it is an outlier."}]}]},"e":"Median 13; Q1 = 8; Q3 = 20; IQR = 12. The upper fence is 20 + 1.5(12) = 38, so 45 minutes lies beyond it and is an outlier. The box plot''s long upper whisker anticipates this.","m":8,"df":"hard","tp":"five-number summary and box plots","st":"five-number summary and box plots","cfg":{"source":"myp-mock-myp4-mock","question_number":25,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Q1 and Q3 are the medians of the lower and upper halves. The 1.5 × IQR fences identify outliers.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the median waiting time, in minutes.","kind":"numeric","points":1,"hints":["With 15 values, which position is the middle?","(15 + 1) ÷ 2 = 8th value."],"strand":"C(i)","answer":13,"tolerance":0,"unit":"minutes"},{"id":"b","label":"(b)","prompt":"State the lower quartile Q1, in minutes.","kind":"numeric","points":2,"hints":["Exclude the median and take the lower seven values.","The middle of 4, 6, 7, 8, 9, 11, 12 is the 4th value."],"strand":"C(ii)","answer":8,"tolerance":0,"unit":"minutes"},{"id":"c","label":"(c)","prompt":"State the upper quartile Q3, in minutes.","kind":"numeric","points":2,"hints":["The upper half is 15, 16, 18, 20, 23, 25, 28.","Its middle value is the 4th."],"strand":"C(ii)","answer":20,"tolerance":0,"unit":"minutes"},{"id":"d","label":"(d)","prompt":"Calculate the IQR, in minutes.","kind":"numeric","points":1,"hints":["The interquartile range is the upper quartile minus the lower quartile.","Subtract your Q1 from your Q3."],"strand":"C(iii)","answer":12,"tolerance":0,"unit":"minutes"},{"id":"e","label":"(e)","prompt":"Decide whether 45 minutes is an outlier and justify with the fence value.","kind":"text","points":2,"hints":["Upper fence = Q3 + 1.5 × IQR.","Compare 45 with 20 + 18."],"strand":"C(iv)","accepted":["yes, it is an outlier: the upper fence is 38 minutes and 45 exceeds it"],"keywords":[["outlier"],["upper"],["fence"],["minutes"],["exceeds"]],"minKeywordGroups":3}],"marking":"(a) 1 mark. (b) 2 marks: 1 for splitting at the median, 1 for 8. (c) 2 marks: 1 for the upper half, 1 for 20. (d) 1 mark for 12. (e) 2 marks: 1 for the fence 38, 1 for the correct conclusion.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for splitting at the median, 1 for 8. (c) 2 marks: 1 for the upper half, 1 for 20. (d) 1 mark for 12. (e) 2 marks: 1 for the fence 38, 1 for the correct conclusion.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Enter the 15 waiting times in the statistics workspace and draw the box plot to check your quartiles.","statistics_chart":"box_plot","response_stats":{"title":"Your statistics construction","instructions":"Enter the 15 waiting times in the statistics workspace and draw the box plot to check your quartiles.","chart":"box_plot","starter":{"chart":"box_plot"}}},"marking":"(a) 1 mark. (b) 2 marks: 1 for splitting at the median, 1 for 8. (c) 2 marks: 1 for the upper half, 1 for 20. (d) 1 mark for 12. (e) 2 marks: 1 for the fence 38, 1 for the correct conclusion.","h1":"Q1 and Q3 are the medians of the lower and upper halves. The 1.5 × IQR fences identify outliers.","h2":"With 15 values, which position is the middle?"},{"n":26,"t":"assess_parts","p":"A grouped frequency table for 50 journey times (minutes) is:\n\n0 ≤ t < 5: 4\n5 ≤ t < 10: 12\n10 ≤ t < 20: 18\n20 ≤ t < 30: 10\n30 ≤ t < 40: 6\n\n(a) Calculate the class width of each class.\n(b) Calculate the frequency density of the class 10 ≤ t < 20.\n(c) Explain why plain frequencies cannot be used as bar heights for this table.\n(d) Calculate the total area of the correct histogram and state what it represents.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A grouped frequency table for 50 journey times (minutes) is:"}]},{"type":"paragraph","content":[{"type":"text","text":"0 ≤ t < 5: 4\n5 ≤ t < 10: 12\n10 ≤ t < 20: 18\n20 ≤ t < 30: 10\n30 ≤ t < 40: 6"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the class width of each class.\n(b) Calculate the frequency density of the class 10 ≤ t < 20.\n(c) Explain why plain frequencies cannot be used as bar heights for this table.\n(d) Calculate the total area of the correct histogram and state what it represents."}]}]},"e":"The densities 0.8, 2.4, 1.8, 1.0, 0.6 give areas 4, 12, 18, 10, 6 which total 50 — exactly the number of journeys. Area is frequency; height alone is not.","m":7,"df":"hard","tp":"histograms","st":"histograms","cfg":{"source":"myp-mock-myp4-mock","question_number":26,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Draw a histogram only from frequency densities when class widths differ: area must equal frequency.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the class width of 20 ≤ t < 30.","kind":"numeric","points":1,"hints":["A class width is the upper boundary minus the lower boundary.","For 20 ≤ t < 30 use 30 − 20."],"strand":"C(i)","answer":10,"tolerance":0,"unit":"minutes"},{"id":"b","label":"(b)","prompt":"Calculate the frequency density of 10 ≤ t < 20.","kind":"numeric","points":2,"hints":["Frequency density = frequency ÷ class width.","18 ÷ 10."],"strand":"C(ii)","answer":1.8,"tolerance":0.01},{"id":"c","label":"(c)","prompt":"Explain why frequencies cannot be used as bar heights here.","kind":"text","points":2,"hints":["Compare the widths: 5 and 10 minutes.","A bar''s area must be proportional to the frequency."],"strand":"C(iii)","accepted":["the class widths are not equal, so equal frequencies would give different areas; heights must be density so that area represents frequency"],"keywords":[["class"],["widths"],["equal"],["frequencies"],["give"],["different"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"Calculate the total area of the histogram.","kind":"numeric","points":2,"hints":["Add density × width for all five classes.","It must equal the total frequency."],"strand":"C(iv)","answer":50,"tolerance":0}],"marking":"(a) 1 mark. (b) 2 marks: 1 for the division, 1 for 1.8. (c) 2 marks: 1 for unequal widths, 1 for the area argument. (d) 2 marks: 1 for the summation, 1 for 50 = total frequency.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for the division, 1 for 1.8. (c) 2 marks: 1 for unequal widths, 1 for the area argument. (d) 2 marks: 1 for the summation, 1 for 50 = total frequency.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Enter the grouped table in the statistics workspace: the chart will plot densities automatically when widths differ.","statistics_chart":"histogram","response_stats":{"title":"Your statistics construction","instructions":"Enter the grouped table in the statistics workspace: the chart will plot densities automatically when widths differ.","chart":"histogram","starter":{"chart":"histogram"}}},"marking":"(a) 1 mark. (b) 2 marks: 1 for the division, 1 for 1.8. (c) 2 marks: 1 for unequal widths, 1 for the area argument. (d) 2 marks: 1 for the summation, 1 for 50 = total frequency.","h1":"Draw a histogram only from frequency densities when class widths differ: area must equal frequency.","h2":"A class width is the upper boundary minus the lower boundary."},{"n":27,"t":"assess_parts","p":"The table gives the marks of 60 students.\n\n0 ≤ m < 10: 5\n10 ≤ m < 20: 12\n20 ≤ m < 30: 15\n30 ≤ m < 40: 16\n40 ≤ m < 50: 12\n\n(a) Construct the cumulative frequency column.\n(b) State the cumulative frequency after the class 30 ≤ m < 40.\n(c) Explain how the median is estimated from a cumulative frequency curve of this table.\n(d) One class is missing its frequency and the total is 60: the first four classes hold 48. Calculate the frequency of the last class.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The table gives the marks of 60 students."}]},{"type":"paragraph","content":[{"type":"text","text":"0 ≤ m < 10: 5\n10 ≤ m < 20: 12\n20 ≤ m < 30: 15\n30 ≤ m < 40: 16\n40 ≤ m < 50: 12"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Construct the cumulative frequency column.\n(b) State the cumulative frequency after the class 30 ≤ m < 40.\n(c) Explain how the median is estimated from a cumulative frequency curve of this table.\n(d) One class is missing its frequency and the total is 60: the first four classes hold 48. Calculate the frequency of the last class."}]}]},"e":"Cumulative totals 5, 17, 32, 48, 60. The median is read at 30, which falls in the class 20 ≤ m < 30; the curve interpolates within that class. The final class frequency is 12.","m":6,"df":"hard","tp":"cumulative frequency","st":"cumulative frequency","cfg":{"source":"myp-mock-myp4-mock","question_number":27,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Cumulative frequency is a running total; read n/2 on the vertical axis to estimate the median.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the cumulative frequency after the class 20 ≤ m < 30.","kind":"numeric","points":1,"hints":["Add the first three frequencies.","5 + 12 + 15."],"strand":"C(i)","answer":32,"tolerance":0},{"id":"b","label":"(b)","prompt":"State the cumulative frequency after 30 ≤ m < 40.","kind":"numeric","points":1,"hints":["Add the frequency 16 to your previous total.","This must be below 60 because one class remains."],"strand":"C(ii)","answer":48,"tolerance":0},{"id":"c","label":"(c)","prompt":"State which cumulative frequency you read to estimate the median.","kind":"numeric","points":1,"hints":["The median is the middle value, so read half of the total on the vertical axis.","Divide the 60 students by 2."],"strand":"C(iii)","answer":30,"tolerance":0},{"id":"d","label":"(d)","prompt":"Calculate the frequency of the last class.","kind":"numeric","points":1,"hints":["The total is 60 and the first four classes hold 48.","60 − 48."],"strand":"C(iii)","answer":12,"tolerance":0},{"id":"e","label":"(e)","prompt":"Explain how the median is obtained from the curve once you reach cumulative frequency 30.","kind":"text","points":2,"hints":["Read across from 30 to the curve, then down to the horizontal axis.","The value read is the estimated median."],"strand":"C(iv)","accepted":["read across from cumulative frequency 30 to the curve, then down to the mark axis; the value found is the estimated median"],"keywords":[["read"],["across"],["cumulative"],["frequency"],["curve"],["down"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 1 mark for 30. (d) 1 mark for 12. (e) 2 marks: 1 for reading across then down, 1 for stating that the value is the median.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 1 mark for 30. (d) 1 mark for 12. (e) 2 marks: 1 for reading across then down, 1 for stating that the value is the median.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Build the grouped table in the workspace to draw the cumulative curve, then answer the boxes.","statistics_chart":"cumulative_frequency","response_stats":{"title":"Your statistics construction","instructions":"Build the grouped table in the workspace to draw the cumulative curve, then answer the boxes.","chart":"cumulative_frequency","starter":{"chart":"cumulative_frequency"}}},"marking":"(a) 1 mark. (b) 1 mark. (c) 1 mark for 30. (d) 1 mark for 12. (e) 2 marks: 1 for reading across then down, 1 for stating that the value is the median.","h1":"Cumulative frequency is a running total; read n/2 on the vertical axis to estimate the median.","h2":"Add the first three frequencies."},{"n":28,"t":"assess_parts","p":"Two bowlers'' scores over 5 games are:\n\nAli: 40, 44, 46, 50, 60\nBen: 30, 42, 48, 52, 68\n\n(a) Calculate the mean score for each bowler.\n(b) Calculate the deviation of each of Ben''s scores from his mean.\n(c) Calculate the population standard deviation of Ben''s scores.\n(d) State which bowler is more consistent and justify your answer.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two bowlers'' scores over 5 games are:"}]},{"type":"paragraph","content":[{"type":"text","text":"Ali: 40, 44, 46, 50, 60\nBen: 30, 42, 48, 52, 68"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the mean score for each bowler.\n(b) Calculate the deviation of each of Ben''s scores from his mean.\n(c) Calculate the population standard deviation of Ben''s scores.\n(d) State which bowler is more consistent and justify your answer."}]}]},"e":"Both means are 48. Ben: deviations −18, −6, 0, 4, 20 give 324 + 36 + 0 + 16 + 400 = 776; variance 155.2; σ ≈ 12.5. Ali: 64 + 16 + 4 + 4 + 144 = 232; variance 46.4; σ ≈ 6.8. Ali is more consistent despite the same mean.","m":9,"df":"hard","tp":"standard deviation","st":"standard deviation","cfg":{"source":"myp-mock-myp4-mock","question_number":28,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Populations σ = √(Σ(x − x̄)² / n). A larger σ means more variability about the mean.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate Ali''s mean score.","kind":"numeric","points":1,"hints":["Add the five scores and divide by 5.","40 + 44 + 46 + 50 + 60."],"strand":"C(i)","answer":48,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate Ben''s mean score.","kind":"numeric","points":1,"hints":["The mean is the total of the scores divided by how many there are.","Ben''s scores total 240 over five games."],"strand":"C(i)","answer":48,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the sum of the squared deviations for Ben, Σ(x − x̄)².","kind":"numeric","points":2,"hints":["Subtract 48 from each score, square it, then add.","(−18)² + (−6)² + 0² + 4² + 20²."],"strand":"C(ii)","answer":776,"tolerance":0},{"id":"d","label":"(d)","prompt":"Calculate Ben''s population standard deviation, to 3 significant figures.","kind":"numeric","points":3,"hints":["Variance = Σ(x − x̄)² ÷ n.","Divide 776 by 5, then take the square root."],"strand":"C(iii)","answer":12.5,"tolerance":0.05},{"id":"e","label":"(e)","prompt":"State which bowler is more consistent and justify your answer.","kind":"text","points":2,"hints":["Compare the standard deviations of Ali and Ben.","A larger standard deviation means more spread."],"strand":"C(iv)","accepted":["ali, because his standard deviation is about 6.8 against ben''s 12.5, so his scores are closer to the mean"],"keywords":[["standard"],["deviation"],["against"],["ben''s"],["scores"],["closer"]],"minKeywordGroups":4}],"marking":"(a) 1 mark for 48. (b) 1 mark for 48. (c) 2 marks: 1 for the deviations, 1 for 776. (d) 3 marks: 1 for dividing by n, 1 for the variance 155.2, 1 for 12.5 (accept 12.4–12.6). (e) 2 marks: 1 for naming Ali, 1 for comparing the two standard deviations.","marking_criteria":"(a) 1 mark for 48. (b) 1 mark for 48. (c) 2 marks: 1 for the deviations, 1 for 776. (d) 3 marks: 1 for dividing by n, 1 for the variance 155.2, 1 for 12.5 (accept 12.4–12.6). (e) 2 marks: 1 for naming Ali, 1 for comparing the two standard deviations.","response_tools":["rich_text","math","statistics"],"response_requirement":"text","response_guidance":"Show the deviations in (c) — the squares are where method marks lie. In (e) compare the two σ values."},"marking":"(a) 1 mark for 48. (b) 1 mark for 48. (c) 2 marks: 1 for the deviations, 1 for 776. (d) 3 marks: 1 for dividing by n, 1 for the variance 155.2, 1 for 12.5 (accept 12.4–12.6). (e) 2 marks: 1 for naming Ali, 1 for comparing the two standard deviations.","h1":"Populations σ = √(Σ(x − x̄)² / n). A larger σ means more variability about the mean.","h2":"Add the five scores and divide by 5."},{"n":29,"t":"assess_parts","p":"A school compares the journey times (minutes) of students and teachers.\n\nStudents (30 students): range 42, IQR 14, median 22\nTeachers (24 teachers): range 55, IQR 9, median 31\n\n(a) State which group has the more variable middle 50% and justify it.\n(b) A governor claims the students have more variable journeys because their range is smaller. Evaluate this claim.\n(c) Using the medians, describe the difference between the two groups.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A school compares the journey times (minutes) of students and teachers."}]},{"type":"paragraph","content":[{"type":"text","text":"Students (30 students): range 42, IQR 14, median 22\nTeachers (24 teachers): range 55, IQR 9, median 31"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State which group has the more variable middle 50% and justify it.\n(b) A governor claims the students have more variable journeys because their range is smaller. Evaluate this claim.\n(c) Using the medians, describe the difference between the two groups."}]}]},"e":"IQR is the spread of the middle half: students 14 > teachers 9. But the teachers'' range of 55 exceeds the students'' 42, so the extremes belong to the teachers. Teachers'' median journey is 9 minutes longer.","m":6,"df":"hard","tp":"comparing data sets","st":"comparing data sets","cfg":{"source":"myp-mock-myp4-mock","question_number":29,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Compare centre and spread separately, and remember the range uses only the two extremes while the IQR uses the middle half.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State which group is more variable in the middle 50%, and justify it.","kind":"text","points":2,"hints":["The IQR measures the middle half of the data.","14 against 9."],"strand":"D(i)","accepted":["students, because their IQR of 14 is larger than the teachers'' 9, so their middle 50% covers a wider range"],"keywords":[["students"],["larger"],["teachers''"],["middle"],["covers"],["wider"]],"minKeywordGroups":4},{"id":"b","label":"(b)","prompt":"Evaluate the governor''s claim about the ranges.","kind":"text","points":2,"hints":["Compare 42 with 55: which range is larger?","The range is sensitive to just two values, the extremes."],"strand":"D(ii)","accepted":["the claim is wrong: the teachers'' range is 55 against the students'' 42, so the teachers'' journeys are more spread at the extremes; the students are only more variable in the middle"],"keywords":[["claim"],["wrong"],["teachers''"],["range"],["against"],["students''"]],"minKeywordGroups":4},{"id":"c","label":"(c)","prompt":"Describe the difference between the groups using the medians.","kind":"text","points":2,"hints":["Compare 31 with 22.","State the difference in minutes and what it means."],"strand":"D(iii)","accepted":["a typical teacher travels about 9 minutes longer than a typical student"],"keywords":[["typical"],["teacher"],["travels"],["minutes"],["longer"],["student"]],"minKeywordGroups":4}],"marking":"(a) 2 marks: 1 for naming students, 1 for citing the IQRs. (b) 2 marks: 1 for correcting the range comparison, 1 for explaining the range''s sensitivity. (c) 2 marks: 1 for the 9-minute difference, 1 for saying what it means.","marking_criteria":"(a) 2 marks: 1 for naming students, 1 for citing the IQRs. (b) 2 marks: 1 for correcting the range comparison, 1 for explaining the range''s sensitivity. (c) 2 marks: 1 for the 9-minute difference, 1 for saying what it means.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Use the specific numbers in each answer; a comparison without figures earns no marks."},"marking":"(a) 2 marks: 1 for naming students, 1 for citing the IQRs. (b) 2 marks: 1 for correcting the range comparison, 1 for explaining the range''s sensitivity. (c) 2 marks: 1 for the 9-minute difference, 1 for saying what it means.","h1":"Compare centre and spread separately, and remember the range uses only the two extremes while the IQR uses the middle half.","h2":"The IQR measures the middle half of the data."},{"n":30,"t":"assess_parts","p":"A company advertises ''average salaries of $48 000'' for 100 employees. The grouped salary data are:\n\n$10 000–20 000: 42 employees\n$20 000–30 000: 26\n$30 000–40 000: 14\n$40 000–60 000: 12\n$60 000–100 000: 6\n\n(a) Calculate the estimated mean using midpoints.\n(b) Explain why the advertised figure may be misleading and suggest a better measure.\n(c) Describe the distribution''s shape from the table.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A company advertises ''average salaries of "},{"type":"text","text":"$48 000'' for 100 employees. The grouped salary data are:"}]},{"type":"paragraph","content":[{"type":"text","text":"$10 000–20 000: 42 employees\n$"},{"type":"text","text":"20 000–30 000: 26\n"},{"type":"text","text":"$30 000–40 000: 14\n$"},{"type":"text","text":"40 000–60 000: 12\n"},{"type":"text","text":"$60 000–100 000: 6"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the estimated mean using midpoints.\n(b) Explain why the advertised figure may be misleading and suggest a better measure.\n(c) Describe the distribution''s shape from the table."}]}]},"e":"Σf x = $2 850 000 over 100 employees gives an estimated mean of $28 500. Since 82% earn under $30 000, the advertised $48 000 misrepresents a typical salary; the median is more representative. The long right tail makes the distribution positively skewed.","m":9,"df":"hard","tp":"histograms","st":"histograms","cfg":{"source":"myp-mock-myp4-mock","question_number":30,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Compare the estimated mean with the advertised claim and ask what a ''typical'' value means when the data are skewed.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the sum of f × midpoint, in dollars.","kind":"numeric","points":2,"hints":["Use midpoints 15 000, 25 000, 35 000, 50 000 and 80 000.","Multiply each by its frequency and add the five products."],"strand":"D(i)","answer":2850000,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the estimated mean salary, in dollars.","kind":"numeric","points":2,"hints":["The estimated mean is Σ(f × midpoint) divided by the total frequency.","Divide your total by the 100 employees."],"strand":"D(ii)","answer":28500,"tolerance":0,"unit":"$"},{"id":"c","label":"(c)","prompt":"Explain why the advertised figure is misleading and state a better measure.","kind":"text","points":3,"hints":["How many employees earn less than $30 000?","Which measure is resistant to a few very high salaries?"],"strand":"D(iii)","accepted":["82 of the 100 employees earn less than $30 000, so $48 000 is not typical; the median is a fairer measure because it is not raised by the few high earners"],"keywords":[["employees"],["earn"],["typical"],["median"],["fairer"],["measure"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"Describe the shape of the distribution, using the table as evidence.","kind":"text","points":2,"hints":["Where is the bulk of the employees?","Is there a long tail at the low or the high end?"],"strand":"D(iv)","accepted":["positively skewed: most employees are in the lower classes with a small tail of very high salaries"],"keywords":[["positively"],["skewed"],["employees"],["lower"],["classes"],["small"]],"minKeywordGroups":4}],"marking":"(a) 2 marks: 1 for the midpoints, 1 for $2 850 000. (b) 2 marks: 1 for dividing by 100, 1 for $28 500. (c) 3 marks: 1 for the comparison, 1 for citing the 82 employees, 1 for recommending the median. (d) 2 marks: 1 for ''positively skewed'', 1 for the evidence.","marking_criteria":"(a) 2 marks: 1 for the midpoints, 1 for $2 850 000. (b) 2 marks: 1 for dividing by 100, 1 for $28 500. (c) 3 marks: 1 for the comparison, 1 for citing the 82 employees, 1 for recommending the median. (d) 2 marks: 1 for ''positively skewed'', 1 for the evidence.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Draw the histogram in the workspace (widths differ, so densities matter) and use it as evidence in (d).","statistics_chart":"histogram","response_stats":{"title":"Your statistics construction","instructions":"Draw the histogram in the workspace (widths differ, so densities matter) and use it as evidence in (d).","chart":"histogram","starter":{"chart":"histogram"}}},"marking":"(a) 2 marks: 1 for the midpoints, 1 for $2 850 000. (b) 2 marks: 1 for dividing by 100, 1 for $28 500. (c) 3 marks: 1 for the comparison, 1 for citing the 82 employees, 1 for recommending the median. (d) 2 marks: 1 for ''positively skewed'', 1 for the evidence.","h1":"Compare the estimated mean with the advertised claim and ask what a ''typical'' value means when the data are skewed.","h2":"Use midpoints 15 000, 25 000, 35 000, 50 000 and 80 000."},{"n":31,"t":"assess_parts","p":"A water tank is filled and then used. Its volume (litres) is recorded hourly for 8 hours:\n\n0 h: 0, 1 h: 120, 2 h: 240, 3 h: 300, 4 h: 300, 5 h: 240, 6 h: 160, 7 h: 80, 8 h: 20\n\n(a) State the interval during which the tank is being filled.\n(b) Calculate the average rate of filling, in litres per hour, during that interval.\n(c) Calculate the average rate of use over the last 5 hours.\n(d) Explain what the horizontal section of the graph represents.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A water tank is filled and then used. Its volume (litres) is recorded hourly for 8 hours:"}]},{"type":"paragraph","content":[{"type":"text","text":"0 h: 0, 1 h: 120, 2 h: 240, 3 h: 300, 4 h: 300, 5 h: 240, 6 h: 160, 7 h: 80, 8 h: 20"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the interval during which the tank is being filled.\n(b) Calculate the average rate of filling, in litres per hour, during that interval.\n(c) Calculate the average rate of use over the last 5 hours.\n(d) Explain what the horizontal section of the graph represents."}]}]},"e":"Filling runs 0→3 h reaching 300 litres: 100 litres/hour. The plateau 3→4 h shows no change. From 4 h to 8 h the volume falls from 300 to 20 litres, so the average use is 280 ÷ 5 = 56 litres/hour.","m":7,"df":"hard","tp":"line graphs","st":"line graphs","cfg":{"source":"myp-mock-myp4-mock","question_number":31,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"On a line graph, the gradient is a rate. A horizontal section means the quantity is constant.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the number of hours the tank is being filled.","kind":"numeric","points":1,"hints":["Find where the volume stops increasing.","It reaches 300 litres and stays there."],"strand":"D(i)","answer":3,"tolerance":0,"unit":"hours"},{"id":"b","label":"(b)","prompt":"Calculate the average rate of filling, in litres per hour.","kind":"numeric","points":2,"hints":["Use the change in volume divided by the time taken.","300 litres in 3 hours."],"strand":"D(ii)","answer":100,"tolerance":0,"unit":"litres/hour"},{"id":"c","label":"(c)","prompt":"Calculate the average rate of use over the last 5 hours, in litres per hour.","kind":"numeric","points":2,"hints":["The volume falls from 300 to 20 litres between 3 h and 8 h.","Divide the 280-litre decrease by 5 hours."],"strand":"D(iii)","answer":56,"tolerance":0,"unit":"litres/hour"},{"id":"d","label":"(d)","prompt":"Explain what the horizontal section represents.","kind":"text","points":2,"hints":["A horizontal line means the volume is not changing.","What would cause no change in volume?"],"strand":"D(iv)","accepted":["the volume is constant between 3 and 4 hours, so no water is added or used during that hour"],"keywords":[["volume"],["constant"],["hours"],["water"],["added"],["used"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 2 marks: 1 for the change and time, 1 for 100. (c) 2 marks: 1 for 280 litres, 1 for 56. (d) 2 marks: 1 for ''constant volume'', 1 for the reason.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for the change and time, 1 for 100. (c) 2 marks: 1 for 280 litres, 1 for 56. (d) 2 marks: 1 for ''constant volume'', 1 for the reason.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot the points in the graph workspace and join them, then read the gradients for (b) and (c)."},"marking":"(a) 1 mark. (b) 2 marks: 1 for the change and time, 1 for 100. (c) 2 marks: 1 for 280 litres, 1 for 56. (d) 2 marks: 1 for ''constant volume'', 1 for the reason.","h1":"On a line graph, the gradient is a rate. A horizontal section means the quantity is constant.","h2":"Find where the volume stops increasing."},{"n":32,"t":"assess_parts","p":"Two classes'' test scores (out of 50) are:\n\nClass 7A: 12, 18, 21, 23, 25, 28, 31, 34, 38, 42, 47\nClass 7B: 15, 17, 19, 20, 22, 26, 29, 33, 35, 39, 44\n\n(a) State the median of Class 7A.\n(b) State the median of Class 7B.\n(c) Explain how a back-to-back stem-and-leaf diagram helps compare the two classes more fairly than the two lists.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two classes'' test scores (out of 50) are:"}]},{"type":"paragraph","content":[{"type":"text","text":"Class 7A: 12, 18, 21, 23, 25, 28, 31, 34, 38, 42, 47\nClass 7B: 15, 17, 19, 20, 22, 26, 29, 33, 35, 39, 44"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the median of Class 7A.\n(b) State the median of Class 7B.\n(c) Explain how a back-to-back stem-and-leaf diagram helps compare the two classes more fairly than the two lists."}]}]},"e":"Both classes have 11 scores. 7A''s median is 28 and 7B''s is 26. The back-to-back diagram shares stems, so a reader can see that 7A has more high scores in the 30s and 40s while 7B is concentrated in the high teens and twenties.","m":4,"df":"hard","tp":"stem-and-leaf diagrams","st":"stem-and-leaf diagrams","cfg":{"source":"myp-mock-myp4-mock","question_number":32,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"A stem-and-leaf diagram keeps every value while sorting it; back-to-back versions share stems so comparisons are visual.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the median of Class 7A.","kind":"numeric","points":1,"hints":["There are 11 scores, so the median is the 6th.","Count in from the lowest."],"strand":"C(i)","answer":28,"tolerance":0},{"id":"b","label":"(b)","prompt":"State the median of Class 7B.","kind":"numeric","points":1,"hints":["Order the 11 scores and take the 6th.","15, 17, 19, 20, 22, 26, ..."],"strand":"C(i)","answer":26,"tolerance":0},{"id":"c","label":"(c)","prompt":"Explain the advantage of a back-to-back stem-and-leaf diagram.","kind":"text","points":2,"hints":["What do both sides share in such a diagram?","Think about comparing spread and shape, not just the median."],"strand":"C(ii)","accepted":["both classes share the same stems, so their spread, shape and centre can be compared directly row by row"],"keywords":[["classes"],["share"],["stems"],["spread"],["shape"],["centre"]],"minKeywordGroups":4}],"marking":"(a) 1 mark for 28. (b) 1 mark for 26. (c) 2 marks: 1 for shared stems, 1 for the comparison benefit.","marking_criteria":"(a) 1 mark for 28. (b) 1 mark for 26. (c) 2 marks: 1 for shared stems, 1 for the comparison benefit.","response_tools":["stem_leaf","rich_text","math"],"response_requirement":"stem_leaf","response_guidance":"Build the back-to-back stem-and-leaf diagram in the workspace (one stem column, a leaf column for each class).","response_stem_leaf":{"title":"Class 7A and Class 7B","instructions":"Construct a back-to-back stem-and-leaf diagram. Keep each class on its own side of the shared stems.","starter":{"layout":"back_to_back","stemLabel":"Tens","leftLeafLabel":"Class 7A leaves","rightLeafLabel":"Class 7B leaves","key":"Key: 2 | 8 means 28"}},"response_default_tool":"stem_leaf"},"marking":"(a) 1 mark for 28. (b) 1 mark for 26. (c) 2 marks: 1 for shared stems, 1 for the comparison benefit.","h1":"A stem-and-leaf diagram keeps every value while sorting it; back-to-back versions share stems so comparisons are visual.","h2":"There are 11 scores, so the median is the 6th."},{"n":33,"t":"assess_parts","p":"The number of books read by 9 students in a month is:\n\n1, 2, 2, 3, 4, 4, 4, 6, 18\n\n(a) State the mode.\n(b) Calculate the mean.\n(c) State the median.\n(d) Explain which measure best represents a typical student here, and why the mean is misleading.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The number of books read by 9 students in a month is:"}]},{"type":"paragraph","content":[{"type":"text","text":"1, 2, 2, 3, 4, 4, 4, 6, 18"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the mode.\n(b) Calculate the mean.\n(c) State the median.\n(d) Explain which measure best represents a typical student here, and why the mean is misleading."}]}]},"e":"Mode 4, median 4, mean 44/9 ≈ 4.89. The single 18 is an outlier that lifts the mean above every value except 18 itself, so the median or mode describes a typical student better.","m":6,"df":"hard","tp":"mean, mode and median","st":"mean, mode and median","cfg":{"source":"myp-mock-myp4-mock","question_number":33,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"When one value is far from the rest, quote the median, and say why the mean is distorted.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the mode.","kind":"numeric","points":1,"hints":["Which value appears most often?","Count the 4s."],"strand":"C(i)","answer":4,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the mean, to 2 decimal places.","kind":"numeric","points":2,"hints":["Add all nine values.","Divide the total by 9."],"strand":"C(ii)","answer":4.89,"tolerance":0.01},{"id":"c","label":"(c)","prompt":"State the median.","kind":"numeric","points":1,"hints":["With nine values the median is the 5th.","One, two, two, three, four, ..."],"strand":"C(iii)","answer":4,"tolerance":0},{"id":"d","label":"(d)","prompt":"State which measure is most representative and explain why the mean misleads.","kind":"text","points":2,"hints":["Which value is far from the others?","How does one extreme value affect a mean?"],"strand":"C(iv)","accepted":["the median (or mode) of 4, because the mean of 4.89 is raised by the single value of 18"],"keywords":[["median"],["mode"],["mean"],["raised"],["single"],["value"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 2 marks: 1 for the total 44, 1 for 4.89. (c) 1 mark. (d) 2 marks: 1 for the choice, 1 for the outlier argument.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for the total 44, 1 for 4.89. (c) 1 mark. (d) 2 marks: 1 for the choice, 1 for the outlier argument.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Enter the values in the statistics workspace and look at the dot plot: the outlier is visible there.","statistics_chart":"dot_plot","response_stats":{"title":"Your statistics construction","instructions":"Enter the values in the statistics workspace and look at the dot plot: the outlier is visible there.","chart":"dot_plot","starter":{"chart":"dot_plot"}}},"marking":"(a) 1 mark. (b) 2 marks: 1 for the total 44, 1 for 4.89. (c) 1 mark. (d) 2 marks: 1 for the choice, 1 for the outlier argument.","h1":"When one value is far from the rest, quote the median, and say why the mean is distorted.","h2":"Which value appears most often?"},{"n":34,"t":"assess_parts","p":"A courier company measures delivery times (minutes) for 40 parcels:\n\n0 ≤ t < 10: 3\n10 ≤ t < 20: 9\n20 ≤ t < 30: 15\n30 ≤ t < 40: 8\n40 ≤ t < 60: 5\n\nAn advertisement promises delivery ''within 25 minutes''. (a) State how many parcels took less than 20 minutes.\n(b) Explain why you cannot read the number under 25 minutes directly from the table.\n(c) Estimate that number using the assumption of even spread within the 20 ≤ t < 30 class.\n(d) Evaluate the advertisement''s claim using your estimate.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A courier company measures delivery times (minutes) for 40 parcels:"}]},{"type":"paragraph","content":[{"type":"text","text":"0 ≤ t < 10: 3\n10 ≤ t < 20: 9\n20 ≤ t < 30: 15\n30 ≤ t < 40: 8\n40 ≤ t < 60: 5"}]},{"type":"paragraph","content":[{"type":"text","text":"An advertisement promises delivery ''within 25 minutes''. (a) State how many parcels took less than 20 minutes.\n(b) Explain why you cannot read the number under 25 minutes directly from the table.\n(c) Estimate that number using the assumption of even spread within the 20 ≤ t < 30 class.\n(d) Evaluate the advertisement''s claim using your estimate."}]}]},"e":"Cumulative totals 3, 12, 27, 35, 40. At 20 minutes, 12 parcels. Assuming even spread, 12 + (5/10)(15) = 19.5 ≈ 20 parcels took under 25 minutes — half the total — so the advert overstates the service.","m":7,"df":"hard","tp":"cumulative frequency","st":"cumulative frequency","cfg":{"source":"myp-mock-myp4-mock","question_number":34,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Cumulative frequency interpolates inside a class: multiply the class frequency by the fraction of the class you have passed.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the cumulative frequency at 20 minutes.","kind":"numeric","points":1,"hints":["Cumulative frequency at 20 minutes is the total of the classes below 20.","Add the frequencies 3 and 9."],"strand":"D(i)","answer":12,"tolerance":0},{"id":"b","label":"(b)","prompt":"Explain why the count for 25 minutes cannot be read directly.","kind":"text","points":1,"hints":["Which class contains 25 minutes?","The table only gives whole-class totals."],"strand":"D(ii)","accepted":["25 lies inside the class 20 ≤ t < 30, and the table only gives the total for the whole class"],"keywords":[["lies"],["inside"],["class"],["table"],["gives"],["total"]],"minKeywordGroups":4},{"id":"c","label":"(c)","prompt":"Estimate how many parcels took less than 25 minutes, assuming an even spread in that class.","kind":"numeric","points":3,"hints":["Half of the 20 ≤ t < 30 class lies below 25 minutes.","Add half of 15 to the 12 you already have."],"strand":"D(iii)","answer":19.5,"tolerance":0.6},{"id":"d","label":"(d)","prompt":"Evaluate the advertisement''s claim.","kind":"text","points":2,"hints":["What percentage of 40 is your estimate?","Does ''within 25 minutes'' describe most deliveries?"],"strand":"D(iv)","accepted":["the claim only holds for about half the deliveries, so it is misleading as a general promise"],"keywords":[["claim"],["holds"],["half"],["deliveries"],["misleading"],["general"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for identifying the class, 1 for the half-class fraction, 1 for 19.5–20. (d) 2 marks: 1 for the percentage, 1 for a fair evaluation.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for identifying the class, 1 for the half-class fraction, 1 for 19.5–20. (d) 2 marks: 1 for the percentage, 1 for a fair evaluation.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Draw the cumulative curve in the workspace and read across at 25 minutes to check your estimate.","statistics_chart":"cumulative_frequency","response_stats":{"title":"Your statistics construction","instructions":"Draw the cumulative curve in the workspace and read across at 25 minutes to check your estimate.","chart":"cumulative_frequency","starter":{"chart":"cumulative_frequency"}}},"marking":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for identifying the class, 1 for the half-class fraction, 1 for 19.5–20. (d) 2 marks: 1 for the percentage, 1 for a fair evaluation.","h1":"Cumulative frequency interpolates inside a class: multiply the class frequency by the fraction of the class you have passed.","h2":"Cumulative frequency at 20 minutes is the total of the classes below 20."},{"n":35,"t":"assess_parts","p":"A supermarket records, for 200 customers: the amount spent (£), whether they used a loyalty card, the number of items bought, and the time spent in the store (minutes).\n\n(a) State which variable is qualitative.\n(b) State which variable is discrete.\n(c) Explain why a histogram is suitable for ''amount spent'' but not for ''loyalty card''.\n(d) Explain one reason the recorded time spent in the store might be unreliable.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A supermarket records, for 200 customers: the amount spent (£), whether they used a loyalty card, the number of items bought, and the time spent in the store (minutes)."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State which variable is qualitative.\n(b) State which variable is discrete.\n(c) Explain why a histogram is suitable for ''amount spent'' but not for ''loyalty card''.\n(d) Explain one reason the recorded time spent in the store might be unreliable."}]}]},"e":"Loyalty card is qualitative, items is discrete, amount spent and time are continuous. A histogram requires numerical classes, which a yes/no variable does not have. Time in store is a measured quantity and is therefore subject to recording error and to customers re-entering.","m":6,"df":"hard","tp":"classification of data","st":"classification of data","cfg":{"source":"myp-mock-myp4-mock","question_number":35,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Match the representation to the data type, and treat measured variables as estimates with error.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Name the qualitative variable.","kind":"text","points":1,"hints":["Which variable is a label rather than an amount?","One of the four has only two possible responses."],"strand":"D(i)","accepted":["loyalty card"]},{"id":"b","label":"(b)","prompt":"Name the discrete variable.","kind":"text","points":1,"hints":["Which variable is counted in whole numbers?","You cannot buy half an item in this record."],"strand":"D(i)","accepted":["number of items bought"],"keywords":[["number"],["items"],["bought"]],"minKeywordGroups":3},{"id":"c","label":"(c)","prompt":"Explain why a histogram suits ''amount spent'' but not ''loyalty card''.","kind":"text","points":2,"hints":["A histogram needs numerical classes.","How many categories does the loyalty card variable have?"],"strand":"D(ii)","accepted":["amount spent is continuous so it can be grouped into numerical classes, while the loyalty card has only two categories, which a bar chart shows"],"keywords":[["amount"],["spent"],["continuous"],["grouped"],["numerical"],["classes"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"Give one reason the recorded time in the store may be unreliable.","kind":"text","points":2,"hints":["How exactly is a customer''s time measured?","Could a customer enter, leave and return?"],"strand":"D(iii)","accepted":["the entry and exit times may not be recorded accurately, or a customer may leave and return so the time is not a single continuous visit"],"keywords":[["entry"],["exit"],["times"],["recorded"],["accurately"],["customer"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for ''needs numerical classes'', 1 for the two-category point. (d) 2 marks: 1 for a concrete cause, 1 for the consequence.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for ''needs numerical classes'', 1 for the two-category point. (d) 2 marks: 1 for a concrete cause, 1 for the consequence.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Give a concrete reason in (d) — ''human error'' alone is too vague to earn the mark."},"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for ''needs numerical classes'', 1 for the two-category point. (d) 2 marks: 1 for a concrete cause, 1 for the consequence.","h1":"Match the representation to the data type, and treat measured variables as estimates with error.","h2":"Which variable is a label rather than an amount?"},{"n":36,"t":"assess_parts","p":"Two groups of runners record their 5 km times (minutes).\n\nGroup A: 18, 20, 21, 22, 24, 25, 30\nGroup B: 19, 23, 23, 24, 25, 26, 27\n\n(a) State the median of each group.\n(b) State Q1 and Q3 for Group A.\n(c) Calculate the IQR of Group B.\n(d) Explain which group is more consistent and justify it with your values.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two groups of runners record their 5 km times (minutes)."}]},{"type":"paragraph","content":[{"type":"text","text":"Group A: 18, 20, 21, 22, 24, 25, 30\nGroup B: 19, 23, 23, 24, 25, 26, 27"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the median of each group.\n(b) State Q1 and Q3 for Group A.\n(c) Calculate the IQR of Group B.\n(d) Explain which group is more consistent and justify it with your values."}]}]},"e":"Medians 22 and 24. Group A: Q1 = 20, Q3 = 25, IQR = 5. Group B: Q1 = 23, Q3 = 26, IQR = 3. Group B is more consistent by both IQR and range.","m":8,"df":"hard","tp":"five-number summary and box plots","st":"five-number summary and box plots","cfg":{"source":"myp-mock-myp4-mock","question_number":36,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Consistency is a statement about spread: compare IQR and range, not the medians.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the median of Group A.","kind":"numeric","points":1,"hints":["With seven values the median is the 4th value in order.","Count in from the lowest: 18, 20, 21, 22."],"strand":"C(i)","answer":22,"tolerance":0},{"id":"b","label":"(b)","prompt":"State the median of Group B.","kind":"numeric","points":1,"hints":["With seven values the median is the 4th value in order.","Count in from the lowest: 19, 23, 23, 24."],"strand":"C(i)","answer":24,"tolerance":0},{"id":"c","label":"(c)","prompt":"State Q1 of Group A.","kind":"numeric","points":1,"hints":["Exclude the median 22 and take the lower three values.","The middle of 18, 20, 21."],"strand":"C(ii)","answer":20,"tolerance":0},{"id":"d","label":"(d)","prompt":"State Q3 of Group A.","kind":"numeric","points":1,"hints":["The upper quartile is the median of the upper half.","The upper three values are 24, 25 and 30."],"strand":"C(ii)","answer":25,"tolerance":0},{"id":"e","label":"(e)","prompt":"Calculate the IQR of Group B.","kind":"numeric","points":2,"hints":["Q1 of B is 23 and Q3 is 26.","IQR = Q3 − Q1."],"strand":"C(iii)","answer":3,"tolerance":0},{"id":"f","label":"(f)","prompt":"State which group is more consistent and justify it.","kind":"text","points":2,"hints":["Compare the two IQRs.","Also compare the two ranges."],"strand":"C(iv)","accepted":["group b, because its IQR of 3 is smaller than group a''s 5 and its range of 8 is smaller than 12","group b is more consistent: IQR 3 against 5"],"keywords":[[["standard deviation","spread","variation","variability","consisten"],["smaller","larger","closer","more","less","compare","mean"]],[["converge","converges","ratio","r","less than 1","|r|"],["shrink","smaller","finite","tends","approaches","sum"]]],"minKeywordGroups":1}],"marking":"(a) 1 mark. (b) 1 mark. (c) 1 mark. (d) 1 mark. (e) 2 marks: 1 for Q1 and Q3, 1 for 3. (f) 2 marks: 1 for naming Group B, 1 for citing both spreads.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 1 mark. (d) 1 mark. (e) 2 marks: 1 for Q1 and Q3, 1 for 3. (f) 2 marks: 1 for naming Group B, 1 for citing both spreads.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Enter both data sets in the statistics workspace to draw comparable box plots, then answer the boxes.","statistics_chart":"box_plot","response_stats":{"title":"Your statistics construction","instructions":"Enter both data sets in the statistics workspace to draw comparable box plots, then answer the boxes.","chart":"box_plot","starter":{"chart":"box_plot"}}},"marking":"(a) 1 mark. (b) 1 mark. (c) 1 mark. (d) 1 mark. (e) 2 marks: 1 for Q1 and Q3, 1 for 3. (f) 2 marks: 1 for naming Group B, 1 for citing both spreads.","h1":"Consistency is a statement about spread: compare IQR and range, not the medians.","h2":"With seven values the median is the 4th value in order."},{"n":37,"t":"assess_parts","p":"A shoe shop records the sizes sold in a day:\n\n3, 4, 4, 5, 5, 5, 5, 6, 6, 7, 8, 8, 9\n\n(a) State the mode and the median.\n(b) Calculate the mean.\n(c) Explain which measure should guide the shop''s ordering decision, and why.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A shoe shop records the sizes sold in a day:"}]},{"type":"paragraph","content":[{"type":"text","text":"3, 4, 4, 5, 5, 5, 5, 6, 6, 7, 8, 8, 9"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the mode and the median.\n(b) Calculate the mean.\n(c) Explain which measure should guide the shop''s ordering decision, and why."}]}]},"e":"Mode 5, median 5, mean 75/13 ≈ 5.77. The mean is pulled up by the sizes 7, 8, 8 and 9, so for stocking decisions the mode is the right measure: it identifies the size with the highest demand.","m":7,"df":"hard","tp":"mean, mode and median","st":"mean, mode and median","cfg":{"source":"myp-mock-myp4-mock","question_number":37,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Choose the measure that fits the decision: the mode for the most common category, the median when there are outliers.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the mode.","kind":"numeric","points":1,"hints":["The mode is the value that appears most often.","Count how many times each size occurs."],"strand":"D(i)","answer":5,"tolerance":0},{"id":"b","label":"(b)","prompt":"State the median.","kind":"numeric","points":1,"hints":["With thirteen values the median is the 7th in order.","Count in from the lowest size."],"strand":"D(i)","answer":5,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the mean, to 2 decimal places.","kind":"numeric","points":2,"hints":["Add all thirteen sizes.","Divide by 13."],"strand":"D(ii)","answer":5.77,"tolerance":0.02},{"id":"d","label":"(d)","prompt":"State which measure should guide ordering and explain why.","kind":"text","points":3,"hints":["The shop needs the size most often requested.","Does the mean overstate demand for any size?"],"strand":"D(iii)","accepted":["the mode of 5, because it is the size most often sold and the shop should stock what customers actually ask for; the mean of 5.77 would over-order larger sizes"],"keywords":[["mode"],["size"],["often"],["sold"],["shop"],["stock"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for the total 75, 1 for 5.77. (d) 3 marks: 1 for the choice, 1 for citing demand, 1 for explaining why the mean misleads.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for the total 75, 1 for 5.77. (d) 3 marks: 1 for the choice, 1 for citing demand, 1 for explaining why the mean misleads.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Draw the bar chart in the workspace to see the demand by size, then answer (d) with the figures.","statistics_chart":"bar_chart","response_stats":{"title":"Your statistics construction","instructions":"Draw the bar chart in the workspace to see the demand by size, then answer (d) with the figures.","chart":"bar_chart","starter":{"chart":"bar_chart"}}},"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for the total 75, 1 for 5.77. (d) 3 marks: 1 for the choice, 1 for citing demand, 1 for explaining why the mean misleads.","h1":"Choose the measure that fits the decision: the mode for the most common category, the median when there are outliers.","h2":"The mode is the value that appears most often."},{"n":38,"t":"assess_parts","p":"A histogram of waiting times is described as: ''The bar for 0 ≤ t < 10 has height 3 and the bar for 10 ≤ t < 30 has height 1.'' (a) Calculate the frequency of each class.\n(b) Explain why a reader might wrongly think there are three times as many people in the first class.\n(c) Calculate the area of each bar and state what the areas show.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A histogram of waiting times is described as: ''The bar for 0 ≤ t < 10 has height 3 and the bar for 10 ≤ t < 30 has height 1.'' (a) Calculate the frequency of each class.\n(b) Explain why a reader might wrongly think there are three times as many people in the first class.\n(c) Calculate the area of each bar and state what the areas show."}]}]},"e":"Heights 3 and 1 over widths 10 and 20 give frequencies 30 and 20, a ratio of 3 : 2, not 3 : 1. The areas of the bars are the frequencies.","m":7,"df":"hard","tp":"histograms","st":"histograms","cfg":{"source":"myp-mock-myp4-mock","question_number":38,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"In a histogram, compare areas, not heights. Frequency = density × class width.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the frequency of 0 ≤ t < 10.","kind":"numeric","points":1,"hints":["Frequency is the area of the bar: density multiplied by class width.","The class is 10 wide and 3 high."],"strand":"D(i)","answer":30,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the frequency of 10 ≤ t < 30.","kind":"numeric","points":2,"hints":["The class 10 ≤ t < 30 is 20 units wide.","Multiply that width by the height 1."],"strand":"D(ii)","answer":20,"tolerance":0},{"id":"c","label":"(c)","prompt":"Explain why reading heights alone is misleading here.","kind":"text","points":2,"hints":["Compare the two class widths.","What does the height represent in a histogram?"],"strand":"D(iii)","accepted":["the bars have different widths, so height is density not frequency; reading the heights suggests three times as many when it is only one and a half times"],"keywords":[["bars"],["different"],["widths"],["height"],["density"],["frequency"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"State what the areas of the two bars represent and give their values.","kind":"text","points":2,"hints":["Area = width × height.","Compare the areas with your frequencies."],"strand":"D(iv)","accepted":["the area of each bar is its frequency, so the areas are 30 and 20"],"keywords":[["area"],["frequency"],["areas"]],"minKeywordGroups":3}],"marking":"(a) 1 mark for 30. (b) 2 marks: 1 for the width 20, 1 for 20. (c) 2 marks: 1 for the widths, 1 for the 3 : 2 explanation. (d) 2 marks: 1 for ''areas = frequencies'', 1 for both values.","marking_criteria":"(a) 1 mark for 30. (b) 2 marks: 1 for the width 20, 1 for 20. (c) 2 marks: 1 for the widths, 1 for the 3 : 2 explanation. (d) 2 marks: 1 for ''areas = frequencies'', 1 for both values.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Enter the grouped table in the workspace; the chart will plot the densities for you to check.","statistics_chart":"histogram","response_stats":{"title":"Your statistics construction","instructions":"Enter the grouped table in the workspace; the chart will plot the densities for you to check.","chart":"histogram","starter":{"chart":"histogram"}}},"marking":"(a) 1 mark for 30. (b) 2 marks: 1 for the width 20, 1 for 20. (c) 2 marks: 1 for the widths, 1 for the 3 : 2 explanation. (d) 2 marks: 1 for ''areas = frequencies'', 1 for both values.","h1":"In a histogram, compare areas, not heights. Frequency = density × class width.","h2":"Frequency is the area of the bar: density multiplied by class width."},{"n":39,"t":"assess_parts","p":"A machine fills bags labelled ''500 g''. A sample of five bags weighs 496, 498, 500, 502 and 504 g.\n\n(a) Calculate the mean mass.\n(b) Calculate the deviations from the mean.\n(c) Calculate the population standard deviation.\n(d) A second sample gives a standard deviation of 6.1 g. Explain what this tells the quality manager, and which sample is closer to the label.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A machine fills bags labelled ''500 g''. A sample of five bags weighs 496, 498, 500, 502 and 504 g."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the mean mass.\n(b) Calculate the deviations from the mean.\n(c) Calculate the population standard deviation.\n(d) A second sample gives a standard deviation of 6.1 g. Explain what this tells the quality manager, and which sample is closer to the label."}]}]},"e":"Mean 500 g; Σ(x − x̄)² = 40; variance 8; σ ≈ 2.83 g. The second sample''s σ of 6.1 g shows far more variability in filling, so it is less precise, although its mean could still be 500 g.","m":9,"df":"hard","tp":"standard deviation","st":"standard deviation","cfg":{"source":"myp-mock-myp4-mock","question_number":39,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"σ measures precision (spread), while the mean measures accuracy (level). Report both when judging a process.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the mean mass, in grams.","kind":"numeric","points":1,"hints":["Add the five masses and divide by 5.","The total is 2500 g."],"strand":"D(i)","answer":500,"tolerance":0,"unit":"g"},{"id":"b","label":"(b)","prompt":"Calculate Σ(x − x̄)² for the sample.","kind":"numeric","points":2,"hints":["Subtract 500 from each mass, then square.","16 + 4 + 0 + 4 + 16."],"strand":"D(ii)","answer":40,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the population standard deviation, to 3 significant figures.","kind":"numeric","points":3,"hints":["Variance = 40 ÷ 5.","Take the square root of 8."],"strand":"D(iii)","answer":2.83,"tolerance":0.02,"unit":"g"},{"id":"d","label":"(d)","prompt":"Explain the meaning of σ = 6.1 g for the second sample.","kind":"text","points":3,"hints":["What does a larger standard deviation measure?","Does the mean have to change as well?"],"strand":"D(iv)","accepted":["the second sample''s masses vary more about their mean, so the process is less precise; a standard deviation of 6.1 g is much larger than 2.83 g so that filling is less consistent","it shows greater variability in filling, so the second process is less precise even if its mean is on target"],"keywords":[[["standard deviation","spread","variation","variability","consisten"],["smaller","larger","closer","more","less","compare","mean"]],[["sample","small","few","20 spins","20 seeds","200 spins","variation","chance"],["too small","random","not enough","larger","more trials","expected","difference"]]],"minKeywordGroups":1}],"marking":"(a) 1 mark for 500 g. (b) 2 marks: 1 for the deviations, 1 for 40. (c) 3 marks: 1 for dividing by 5, 1 for the variance 8, 1 for 2.83. (d) 3 marks: 1 for ''more variable'', 1 for ''less precise'', 1 for separating accuracy from precision.","marking_criteria":"(a) 1 mark for 500 g. (b) 2 marks: 1 for the deviations, 1 for 40. (c) 3 marks: 1 for dividing by 5, 1 for the variance 8, 1 for 2.83. (d) 3 marks: 1 for ''more variable'', 1 for ''less precise'', 1 for separating accuracy from precision.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Enter the five masses in the workspace as a dot plot to see the symmetry before computing.","statistics_chart":"dot_plot","response_stats":{"title":"Your statistics construction","instructions":"Enter the five masses in the workspace as a dot plot to see the symmetry before computing.","chart":"dot_plot","starter":{"chart":"dot_plot"}}},"marking":"(a) 1 mark for 500 g. (b) 2 marks: 1 for the deviations, 1 for 40. (c) 3 marks: 1 for dividing by 5, 1 for the variance 8, 1 for 2.83. (d) 3 marks: 1 for ''more variable'', 1 for ''less precise'', 1 for separating accuracy from precision.","h1":"σ measures precision (spread), while the mean measures accuracy (level). Report both when judging a process.","h2":"Add the five masses and divide by 5."},{"n":40,"t":"assess_parts","p":"A cinema surveys 80 customers about travel time (minutes) to the cinema:\n\n0 ≤ t < 10: 20\n10 ≤ t < 20: 28\n20 ≤ t < 40: 24\n40 ≤ t < 60: 8\n\n(a) Calculate the estimated mean travel time.\n(b) Explain one limitation of the estimated mean compared with the true mean.\n(c) The cinema proposes a free bus for customers who travel more than 20 minutes. Using your table, state how many would qualify, and explain one assumption your answer relies on.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A cinema surveys 80 customers about travel time (minutes) to the cinema:"}]},{"type":"paragraph","content":[{"type":"text","text":"0 ≤ t < 10: 20\n10 ≤ t < 20: 28\n20 ≤ t < 40: 24\n40 ≤ t < 60: 8"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the estimated mean travel time.\n(b) Explain one limitation of the estimated mean compared with the true mean.\n(c) The cinema proposes a free bus for customers who travel more than 20 minutes. Using your table, state how many would qualify, and explain one assumption your answer relies on."}]}]},"e":"Σf x = 1640 over 80 customers gives 20.5 minutes. The midpoint assumption flattens variation inside the wide classes. Customers over 20 minutes are 24 + 8 = 32, assuming the class boundary matches ''more than 20''.","m":8,"df":"hard","tp":"grouped data","st":"grouped data","cfg":{"source":"myp-mock-myp4-mock","question_number":40,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"An estimated mean from grouped data is always an approximation; state the midpoint assumption when you interpret it.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate Σ(f × midpoint).","kind":"numeric","points":2,"hints":["Midpoints are 5, 15, 30 and 50.","Multiply each by its frequency and add."],"strand":"D(i)","answer":1640,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the estimated mean travel time, in minutes.","kind":"numeric","points":2,"hints":["The estimated mean is Σ(f × midpoint) divided by the total frequency.","Divide your 1640 by the 80 customers."],"strand":"D(ii)","answer":20.5,"tolerance":0.01,"unit":"minutes"},{"id":"c","label":"(c)","prompt":"Explain one limitation of this estimated mean.","kind":"text","points":2,"hints":["Where does the estimate place every value in a class?","Is that realistic?"],"strand":"D(iii)","accepted":["it assumes every value in a class is at the midpoint, so it ignores the real spread within each class and is only an estimate"],"keywords":[["assumes"],["value"],["class"],["midpoint"],["ignores"],["real"]],"minKeywordGroups":4},{"id":"d","label":"(d)","prompt":"State how many customers travel more than 20 minutes, and one assumption behind it.","kind":"text","points":2,"hints":["Add the two classes above 20 minutes.","Does the table show anyone exactly at 20 minutes?"],"strand":"D(iv)","accepted":["32 customers, assuming the 20 ≤ t < 40 class is correctly classified as more than 20 minutes and that each customer answered once"],"keywords":[["customers"],["assuming"],["class"],["correctly"],["classified"],["minutes"]],"minKeywordGroups":4}],"marking":"(a) 2 marks: 1 for the midpoints, 1 for 1640. (b) 2 marks: 1 for dividing by 80, 1 for 20.5. (c) 2 marks: 1 for the midpoint assumption, 1 for its effect. (d) 2 marks: 1 for 32, 1 for a valid assumption.","marking_criteria":"(a) 2 marks: 1 for the midpoints, 1 for 1640. (b) 2 marks: 1 for dividing by 80, 1 for 20.5. (c) 2 marks: 1 for the midpoint assumption, 1 for its effect. (d) 2 marks: 1 for 32, 1 for a valid assumption.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"Draw the histogram in the workspace (the 20-minute and 20-wide classes need densities) and use it in (c).","statistics_chart":"histogram","response_stats":{"title":"Your statistics construction","instructions":"Draw the histogram in the workspace (the 20-minute and 20-wide classes need densities) and use it in (c).","chart":"histogram","starter":{"chart":"histogram"}}},"marking":"(a) 2 marks: 1 for the midpoints, 1 for 1640. (b) 2 marks: 1 for dividing by 80, 1 for 20.5. (c) 2 marks: 1 for the midpoint assumption, 1 for its effect. (d) 2 marks: 1 for 32, 1 for a valid assumption.","h1":"An estimated mean from grouped data is always an approximation; state the midpoint assumption when you interpret it.","h2":"Midpoints are 5, 15, 30 and 50."},{"n":41,"t":"assess_parts","p":"A school records the number of minutes 50 students spend on homework. The cumulative frequency curve shows the median at 42 minutes, Q1 at 28 minutes and Q3 at 58 minutes.\n\n(a) State the interquartile range.\n(b) Explain what the IQR tells the school that the median alone does not.\n(c) A teacher claims ''most students work about 42 minutes''. Evaluate the claim using the quartiles.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A school records the number of minutes 50 students spend on homework. The cumulative frequency curve shows the median at 42 minutes, Q1 at 28 minutes and Q3 at 58 minutes."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the interquartile range.\n(b) Explain what the IQR tells the school that the median alone does not.\n(c) A teacher claims ''most students work about 42 minutes''. Evaluate the claim using the quartiles."}]}]},"e":"IQR = 30 minutes. The median locates the middle student; the IQR shows the middle half span 28–58 minutes, so the teacher''s ''about 42 minutes'' is a central value that conceals wide variation.","m":6,"df":"hard","tp":"cumulative frequency","st":"cumulative frequency","cfg":{"source":"myp-mock-myp4-mock","question_number":41,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Pairs of measures tell the whole story: a measure of centre plus a measure of spread.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the interquartile range, in minutes.","kind":"numeric","points":1,"hints":["IQR = Q3 − Q1.","58 − 28."],"strand":"D(i)","answer":30,"tolerance":0,"unit":"minutes"},{"id":"b","label":"(b)","prompt":"Explain what the IQR adds to the median.","kind":"text","points":2,"hints":["What does the IQR measure?","Which half of the students does it describe?"],"strand":"D(ii)","accepted":["the IQR describes the spread of the middle half of the students, whereas the median gives only one central value"],"keywords":[["describes"],["spread"],["middle"],["half"],["students"],["whereas"]],"minKeywordGroups":4},{"id":"c","label":"(c)","prompt":"Evaluate the teacher''s claim using the quartiles.","kind":"text","points":3,"hints":["Half the students work more than 42 minutes and half less.","How wide is the range of the middle half?"],"strand":"D(iii)","accepted":["the median does show a typical student at 42 minutes, but the middle half spread over 28 to 58 minutes, so ''about 42 minutes'' hides a wide variation"],"keywords":[["median"],["show"],["typical"],["student"],["minutes"],["middle"]],"minKeywordGroups":4}],"marking":"(a) 1 mark for 30. (b) 2 marks: 1 for ''spread of the middle half'', 1 for the contrast with the median. (c) 3 marks: 1 for accepting the median value, 1 for citing 28–58, 1 for judging the claim''s limitation.","marking_criteria":"(a) 1 mark for 30. (b) 2 marks: 1 for ''spread of the middle half'', 1 for the contrast with the median. (c) 3 marks: 1 for accepting the median value, 1 for citing 28–58, 1 for judging the claim''s limitation.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Quote the quartiles in (c) — an evaluation without figures is just an opinion."},"marking":"(a) 1 mark for 30. (b) 2 marks: 1 for ''spread of the middle half'', 1 for the contrast with the median. (c) 3 marks: 1 for accepting the median value, 1 for citing 28–58, 1 for judging the claim''s limitation.","h1":"Pairs of measures tell the whole story: a measure of centre plus a measure of spread.","h2":"IQR = Q3 − Q1."},{"n":42,"t":"assess_parts","p":"Two classes sit the same test out of 40.\n\nClass X: mean 26, median 27, range 22, standard deviation 5.2\nClass Y: mean 26, median 25, range 24, standard deviation 9.4\n\n(a) State which class has the more consistent results and justify it.\n(b) Explain what the medians suggest about the shape of each distribution.\n(c) A parent concludes ''the classes performed equally because both means are 26''. Evaluate this conclusion.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two classes sit the same test out of 40."}]},{"type":"paragraph","content":[{"type":"text","text":"Class X: mean 26, median 27, range 22, standard deviation 5.2\nClass Y: mean 26, median 25, range 24, standard deviation 9.4"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State which class has the more consistent results and justify it.\n(b) Explain what the medians suggest about the shape of each distribution.\n(c) A parent concludes ''the classes performed equally because both means are 26''. Evaluate this conclusion."}]}]},"e":"σ tells us Class X is far more consistent. Median > mean suggests a low tail (X); median < mean suggests a high tail (Y). Equal means therefore mask very different distributions.","m":8,"df":"hard","tp":"comparing data sets","st":"comparing data sets","cfg":{"source":"myp-mock-myp4-mock","question_number":42,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"Never judge two distributions on one measure. Centre, spread and shape each answer a different question.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State which class is more consistent and justify it.","kind":"text","points":2,"hints":["Compare the two standard deviations.","Which one is smaller?"],"strand":"D(i)","accepted":["class x, because its standard deviation of 5.2 is smaller than class y''s 9.4, so its marks are closer together"],"keywords":[["class"],["standard"],["deviation"],["smaller"],["marks"],["closer"]],"minKeywordGroups":4},{"id":"b","label":"(b)","prompt":"Explain what the medians suggest about each distribution''s shape.","kind":"text","points":3,"hints":["Compare the median with the mean in each class.","If the median is below the mean, where is the tail?"],"strand":"D(ii)","accepted":["class x has median above mean, suggesting a low tail; class y has median below mean, suggesting a high tail pulling the mean up"],"keywords":[["class"],["median"],["above"],["mean"],["suggesting"],["tail"]],"minKeywordGroups":4},{"id":"c","label":"(c)","prompt":"Evaluate the parent''s conclusion.","kind":"text","points":3,"hints":["Do equal means imply equal performance?","Use the spreads and medians in your answer."],"strand":"D(iii)","accepted":["the means are equal but the distributions differ: class y is far more variable and its median is lower, so equal means do not mean equal performance"],"keywords":[["means"],["equal"],["distributions"],["differ"],["class"],["variable"]],"minKeywordGroups":4}],"marking":"(a) 2 marks: 1 for naming X, 1 for citing σ. (b) 3 marks: 1 for the comparison method, 1 for X''s low tail, 1 for Y''s high tail. (c) 3 marks: 1 for rejecting the conclusion, 1 for the spread evidence, 1 for a classroom consequence.","marking_criteria":"(a) 2 marks: 1 for naming X, 1 for citing σ. (b) 3 marks: 1 for the comparison method, 1 for X''s low tail, 1 for Y''s high tail. (c) 3 marks: 1 for rejecting the conclusion, 1 for the spread evidence, 1 for a classroom consequence.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Compare centre, spread and skew separately in your answers; each is a distinct piece of evidence."},"marking":"(a) 2 marks: 1 for naming X, 1 for citing σ. (b) 3 marks: 1 for the comparison method, 1 for X''s low tail, 1 for Y''s high tail. (c) 3 marks: 1 for rejecting the conclusion, 1 for the spread evidence, 1 for a classroom consequence.","h1":"Never judge two distributions on one measure. Centre, spread and shape each answer a different question.","h2":"Compare the two standard deviations."},{"n":43,"t":"assess_parts","p":"A stem-and-leaf diagram of 20 masses, in grams, begins:\n\n2 | 1 4\n3 | 0 2 2 5 8\n4 | 1 4 6 9\n5 | 0 3\nKey: 3 | 2 means 32 g\n\n(a) State the smallest mass.\n(b) State how many masses are in the 40s.\n(c) State the mode.\n(d) A student says the median is 45. Without recalculating, explain why this cannot be correct.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A stem-and-leaf diagram of 20 masses, in grams, begins:"}]},{"type":"paragraph","content":[{"type":"text","text":"2 | 1 4\n3 | 0 2 2 5 8\n4 | 1 4 6 9\n5 | 0 3\nKey: 3 | 2 means 32 g"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the smallest mass.\n(b) State how many masses are in the 40s.\n(c) State the mode.\n(d) A student says the median is 45. Without recalculating, explain why this cannot be correct."}]}]},"e":"Smallest 21; four values in the 40s; mode 32. For n = 20 the median is the average of the 10th and 11th values, so it is not simply read off one leaf, and 45 does not correspond to the leaves at those positions.","m":6,"df":"hard","tp":"stem-and-leaf diagrams","st":"stem-and-leaf diagrams","cfg":{"source":"myp-mock-myp4-mock","question_number":43,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"Locate the median by position (n/2), not by eye. For an even n the median need not be a data value.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"State the smallest mass, in grams.","kind":"numeric","points":1,"hints":["Read the key: the stem gives the tens.","The first leaf in the diagram is on stem 2."],"strand":"C(i)","answer":21,"tolerance":0,"unit":"g"},{"id":"b","label":"(b)","prompt":"State how many masses are in the 40s.","kind":"numeric","points":1,"hints":["Every leaf on stem 4 is a mass in the forties.","Count the leaves 1, 4, 6 and 9."],"strand":"C(i)","answer":4,"tolerance":0},{"id":"c","label":"(c)","prompt":"State the mode, in grams.","kind":"numeric","points":1,"hints":["Which leaf value is repeated?","Look at stem 3."],"strand":"C(ii)","answer":32,"tolerance":0,"unit":"g"},{"id":"d","label":"(d)","prompt":"Explain why a median of 45 g cannot be correct.","kind":"text","points":3,"hints":["With 20 values, the median is the average of the 10th and 11th.","Which values actually occupy those positions?"],"strand":"C(iii)","accepted":["with 20 values the median is the mean of the 10th and 11th values, which lie in the 40s row, but 45 is not a value in the diagram and a median need not be a data value, so 45 cannot be checked off the leaves"],"keywords":[["values"],["median"],["mean"],["10th"],["11th"],["value"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 1 mark. (d) 3 marks: 1 for the position rule, 1 for locating the 10th and 11th, 1 for concluding why 45 fails.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 1 mark. (d) 3 marks: 1 for the position rule, 1 for locating the 10th and 11th, 1 for concluding why 45 fails.","response_tools":["stem_leaf","rich_text","math"],"response_requirement":"stem_leaf","response_guidance":"Rebuild the stem-and-leaf diagram in the workspace and count positions — the position of the median is the argument.","response_stem_leaf":{"title":"Masses stem-and-leaf diagram","instructions":"Rebuild the stem-and-leaf diagram with its key and ordered leaves. Use the completed diagram to identify the median positions.","starter":{"layout":"standard","stemLabel":"Tens","leafLabel":"Units","key":"Key: 3 | 2 means 32 g"}},"response_default_tool":"stem_leaf"},"marking":"(a) 1 mark. (b) 1 mark. (c) 1 mark. (d) 3 marks: 1 for the position rule, 1 for locating the 10th and 11th, 1 for concluding why 45 fails.","h1":"Locate the median by position (n/2), not by eye. For an even n the median need not be a data value.","h2":"Read the key: the stem gives the tens."},{"n":44,"t":"assess_parts","p":"A line graph shows a town''s recycling rate (%) each year: 2018: 12, 2019: 18, 2020: 24, 2021: 23, 2022: 29, 2023: 35.\n\n(a) Calculate the change in the recycling rate from 2018 to 2023.\n(b) State the year in which the rate fell, and by how many percentage points.\n(c) Calculate the mean yearly increase from 2018 to 2023, and explain why it may not predict 2024 accurately.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A line graph shows a town''s recycling rate (%) each year: 2018: 12, 2019: 18, 2020: 24, 2021: 23, 2022: 29, 2023: 35."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the change in the recycling rate from 2018 to 2023.\n(b) State the year in which the rate fell, and by how many percentage points.\n(c) Calculate the mean yearly increase from 2018 to 2023, and explain why it may not predict 2024 accurately."}]}]},"e":"12 → 35 is +23 points. The 2020→2021 change was a 1-point fall. The mean yearly increase over five intervals is 4.6 points, but extrapolating is unsound: growth is uneven and may saturate.","m":7,"df":"hard","tp":"line graphs","st":"line graphs","cfg":{"source":"myp-mock-myp4-mock","question_number":44,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"An average rate of change smooths over the actual path; before extrapolating, check for reversals and ceilings.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the increase from 2018 to 2023, in percentage points.","kind":"numeric","points":1,"hints":["Subtract the 2018 value from the 2023 value.","35 − 12."],"strand":"D(i)","answer":23,"tolerance":0},{"id":"b","label":"(b)","prompt":"State the size of the fall in the year it decreased, in percentage points.","kind":"numeric","points":1,"hints":["Compare consecutive years.","2020 was 24 and 2021 was 23."],"strand":"D(i)","answer":1,"tolerance":0},{"id":"c","label":"(c)","prompt":"Calculate the mean yearly increase from 2018 to 2023.","kind":"numeric","points":2,"hints":["There are five yearly intervals between 2018 and 2023.","Divide 23 by 5."],"strand":"D(ii)","answer":4.6,"tolerance":0.05},{"id":"d","label":"(d)","prompt":"Explain why this mean increase may not predict 2024 accurately.","kind":"text","points":3,"hints":["Is the trend perfectly steady?","What happens to a percentage rate as it approaches its maximum?"],"strand":"D(iii)","accepted":["the trend is not perfectly steady because one year fell, and growth is likely to slow as the rate approaches a practical maximum, so a simple average overstates future rises"],"keywords":[["trend"],["perfectly"],["steady"],["year"],["fell"],["growth"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for the number of intervals, 1 for 4.6. (d) 3 marks: 1 for noting the fall, 1 for a ceiling argument, 1 for the conclusion about prediction.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for the number of intervals, 1 for 4.6. (d) 3 marks: 1 for noting the fall, 1 for a ceiling argument, 1 for the conclusion about prediction.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot the six points in the workspace and join them, then read the trend before answering (d)."},"marking":"(a) 1 mark. (b) 1 mark. (c) 2 marks: 1 for the number of intervals, 1 for 4.6. (d) 3 marks: 1 for noting the fall, 1 for a ceiling argument, 1 for the conclusion about prediction.","h1":"An average rate of change smooths over the actual path; before extrapolating, check for reversals and ceilings.","h2":"Subtract the 2018 value from the 2023 value."},{"n":45,"t":"assess_parts","p":"A researcher collects two data sets about the same 50 students.\n\nSet P: the score on a 100-mark test.\nSet Q: the time taken to complete the test, in minutes.\n\nThe researcher writes: ''Both data sets are quantitative, so both should be shown in a histogram with the same class widths.''\n\n(a) Explain what is correct in the statement.\n(b) Explain what is incorrect in the statement.\n(c) State the class width measured in marks that would be unsuitable for the time data, and explain why.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A researcher collects two data sets about the same 50 students."}]},{"type":"paragraph","content":[{"type":"text","text":"Set P: the score on a 100-mark test.\nSet Q: the time taken to complete the test, in minutes."}]},{"type":"paragraph","content":[{"type":"text","text":"The researcher writes: ''Both data sets are quantitative, so both should be shown in a histogram with the same class widths.''"}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Explain what is correct in the statement.\n(b) Explain what is incorrect in the statement.\n(c) State the class width measured in marks that would be unsuitable for the time data, and explain why."}]}]},"e":"Both variables are quantitative, so histograms are appropriate. But class widths must be chosen per variable: 10 marks suits a 0–100 range, while 10 minutes is too coarse for a typically 20–70 minute range, where 5-minute classes reveal the shape.","m":6,"df":"hard","tp":"classification of data","st":"classification of data","cfg":{"source":"myp-mock-myp4-mock","question_number":45,"paper_section":"B","myp_criterion":"B","strand":"B(i)","next_time_hint":"Choose class widths from the range and the unit of the variable, not from a template.","assessment_style":"myp_mock","mock_exam_key":"myp4-mock","parts":[{"id":"a","label":"(a)","prompt":"Explain what is correct in the researcher''s statement.","kind":"text","points":1,"hints":["Are both variables numerical?","Can numerical data be grouped into classes?"],"strand":"B(i)","accepted":["both variables are quantitative, so a histogram is a suitable representation for each"],"keywords":[["variables"],["quantitative"],["histogram"],["suitable"],["representation"]],"minKeywordGroups":3},{"id":"b","label":"(b)","prompt":"Explain what is incorrect in the statement.","kind":"text","points":2,"hints":["Do marks and minutes have the same range?","Should the class width depend on the variable?"],"strand":"B(ii)","accepted":["the class widths must suit each variable''s range and units; using the same widths for both misrepresents the time data"],"keywords":[["class"],["widths"],["suit"],["variable''s"],["range"],["units"]],"minKeywordGroups":4},{"id":"c","label":"(c)","prompt":"State a class width in marks that would be unsuitable for the time data, and explain why.","kind":"text","points":3,"hints":["A width of 10 is reasonable for marks out of 100.","How many classes would that leave for a time range of about 50 minutes?"],"strand":"B(iii)","accepted":["10 marks: for a time range of about 50 minutes it would create only about five classes, losing detail that a 5-minute width would show"],"keywords":[["marks"],["time"],["range"],["minutes"],["create"],["five"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 2 marks: 1 for ''widths must suit the data'', 1 for the consequence. (c) 3 marks: 1 for naming a width, 1 for the range argument, 1 for the information lost.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for ''widths must suit the data'', 1 for the consequence. (c) 3 marks: 1 for naming a width, 1 for the range argument, 1 for the information lost.","response_tools":["statistics","rich_text","math"],"response_requirement":"statistics","response_guidance":"You may build both histograms in the workspace to see the effect of the class width.","statistics_chart":"histogram","response_stats":{"title":"Your statistics construction","instructions":"You may build both histograms in the workspace to see the effect of the class width.","chart":"histogram","starter":{"chart":"histogram"}}},"marking":"(a) 1 mark. (b) 2 marks: 1 for ''widths must suit the data'', 1 for the consequence. (c) 3 marks: 1 for naming a width, 1 for the range argument, 1 for the information lost.","h1":"Choose class widths from the range and the unit of the variable, not from a template.","h2":"Are both variables numerical?"}]'::jsonb) as x;

create temporary table _myp_mock_forward_options (
  option_id uuid primary key,
  question_id uuid not null,
  position integer not null,
  label text not null,
  is_correct boolean not null,
  unique (question_id, position)
) on commit drop;

insert into _myp_mock_forward_options (option_id, question_id, position, label, is_correct)
select ('d4000000-0000-4000-8000' || lpad((300000 + s.question_number * 100 + v.position::integer)::text, 12, '0'))::uuid,
       s.question_id, v.position::integer, v.label,
       (s.config->'option_key') @> to_jsonb(v.position::integer)
  from _myp_mock_forward_stage s
 cross join lateral jsonb_array_elements_text(coalesce(s.config->'option_labels', '[]'::jsonb)) with ordinality as v(label, position);

insert into _myp_mock_forward_options (option_id, question_id, position, label, is_correct)
select ('d4000000-0000-4000-8000' || lpad((310000 + s.question_number * 100 + v.position::integer)::text, 12, '0'))::uuid,
       s.question_id, v.position::integer, v.label, true
  from _myp_mock_forward_stage s
 cross join lateral jsonb_array_elements_text(coalesce(s.config->'accepted', '[]'::jsonb)) with ordinality as v(label, position);

create temporary table _myp_mock_forward_hints (
  hint_id uuid primary key,
  question_id uuid not null,
  level smallint not null,
  body text not null,
  unique (question_id, level)
) on commit drop;

insert into _myp_mock_forward_hints (hint_id, question_id, level, body)
select ('d4000000-0000-4000-8000' || lpad((500000 + s.question_number * 10 + v.level)::text, 12, '0'))::uuid,
       s.question_id, v.level::smallint, v.body
  from _myp_mock_forward_stage s
 cross join lateral (values (1, s.hint_one), (2, s.hint_two)) as v(level, body)
 where v.body is not null and char_length(btrim(v.body)) between 8 and 800;

do $$
declare
  v_questions integer;
  v_paper_rows integer;
  v_attempts integer;
  v_extra_options integer;
  v_duplicate_positions integer;
  v_id_collisions integer;
  v_other_paper_links integer;
begin
  -- A row lock prevents a new attempt from being created between this check and
  -- the content update below. If a paper has ever been attempted, stop rather
  -- than reinterpret a candidate's saved response against new question text.
  perform 1 from public.exams
   where id = 'd4000000-0000-4000-8000-000000000002'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP4-MOCK-2026: fixed examination row is missing or belongs to another tenant';
  end if;
  perform 1 from public.quizzes
   where id = 'd4000000-0000-4000-8000-000000000001'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP4-MOCK-2026: fixed quiz row is missing or belongs to another tenant';
  end if;
  if not exists (
    select 1 from public.exams
     where id = 'd4000000-0000-4000-8000-000000000002'::uuid
       and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and quiz_id = 'd4000000-0000-4000-8000-000000000001'::uuid
  ) then
    raise exception 'MYP4-MOCK-2026: the fixed examination is no longer linked to its fixed quiz row';
  end if;

  select count(*) into v_attempts from public.exam_attempts where exam_id = 'd4000000-0000-4000-8000-000000000002'::uuid;
  if v_attempts <> 0 then
    raise exception 'MYP4-MOCK-2026: refusing to rewrite a paper with % attempt(s); preserve active and historical sessions, then retry with an approved snapshot plan', v_attempts;
  end if;

  select count(*) into v_questions
    from _myp_mock_forward_stage s
    join public.questions q on q.id = s.question_id and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid;
  if v_questions <> 45 then
    raise exception 'MYP4-MOCK-2026: found % of the expected 45 fixed question rows', v_questions;
  end if;

  select count(*) into v_paper_rows
    from _myp_mock_forward_stage s
    join public.quiz_questions qq on qq.question_id = s.question_id and qq.quiz_id = 'd4000000-0000-4000-8000-000000000001'::uuid;
  if v_paper_rows <> 45 then
    raise exception 'MYP4-MOCK-2026: found % of the expected 45 fixed quiz-question rows', v_paper_rows;
  end if;
  select count(*) into v_other_paper_links
    from public.quiz_questions qq
    join _myp_mock_forward_stage s on s.question_id = qq.question_id
   where qq.quiz_id <> 'd4000000-0000-4000-8000-000000000001'::uuid;
  if v_other_paper_links <> 0 then
    raise exception 'MYP4-MOCK-2026: % target question link(s) belong to another quiz; refusing to rewrite shared content', v_other_paper_links;
  end if;

  -- Existing options must be representable by the authored positions. We may
  -- update those rows in place or add a missing row, but never delete or remap
  -- an unexpected option because an historical answer may reference its UUID.
  select count(*) into v_extra_options
    from public.question_options o
    join _myp_mock_forward_stage s on s.question_id = o.question_id
   where not exists (
     select 1 from _myp_mock_forward_options d
      where d.question_id = o.question_id and d.position = o.position
   );
  if v_extra_options <> 0 then
    raise exception 'MYP4-MOCK-2026: % unexpected option row(s) would require destructive cleanup', v_extra_options;
  end if;

  select count(*) into v_duplicate_positions
    from (
      select o.question_id, o.position
        from public.question_options o
        join _myp_mock_forward_stage s on s.question_id = o.question_id
       group by o.question_id, o.position
      having count(*) > 1
    ) duplicates;
  if v_duplicate_positions <> 0 then
    raise exception 'MYP4-MOCK-2026: duplicate option positions require manual reconciliation';
  end if;

  select count(*) into v_id_collisions
    from _myp_mock_forward_options d
    join public.question_options o on o.id = d.option_id
   where o.question_id <> d.question_id or o.position <> d.position;
  if v_id_collisions <> 0 then
    raise exception 'MYP4-MOCK-2026: deterministic option IDs collide with unrelated rows';
  end if;
end $$;

update public.questions q
   set type = s.question_type,
       prompt = s.prompt,
       prompt_doc = s.prompt_doc,
       explanation = s.explanation,
       explanation_doc = null,
       points = s.points,
       difficulty = s.difficulty,
       topic = s.topic,
       subtopic = s.subtopic,
       tags = array['MYP 4', 'Mathematics', 'mock', 'mock-examination', 'MYP4-MOCK-2026'],
       config = s.config,
       curriculum = 'MYP',
       curriculum_course = 'MYP 4 Mathematics',
       subject_id = '0a400000-0000-4000-8000-000000000030'::uuid
  from _myp_mock_forward_stage s
 where q.id = s.question_id
   and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   and (
     q.type is distinct from s.question_type
     or q.prompt is distinct from s.prompt
     or q.prompt_doc is distinct from s.prompt_doc
     or q.explanation is distinct from s.explanation
     or q.explanation_doc is not null
     or q.points is distinct from s.points
     or q.difficulty is distinct from s.difficulty
     or q.topic is distinct from s.topic
     or q.subtopic is distinct from s.subtopic
     or q.tags is distinct from array['MYP 4', 'Mathematics', 'mock', 'mock-examination', 'MYP4-MOCK-2026']
     or q.config is distinct from s.config
     or q.curriculum is distinct from 'MYP'
     or q.curriculum_course is distinct from 'MYP 4 Mathematics'
     or q.subject_id is distinct from '0a400000-0000-4000-8000-000000000030'::uuid
   );

update public.question_options o
   set label = d.label,
       is_correct = d.is_correct,
       content_doc = null
  from _myp_mock_forward_options d
 where o.question_id = d.question_id
   and o.position = d.position
   and (o.label is distinct from d.label or o.is_correct is distinct from d.is_correct or o.content_doc is not null);

insert into public.question_options (id, question_id, label, is_correct, position, content_doc)
select d.option_id, d.question_id, d.label, d.is_correct, d.position, null
  from _myp_mock_forward_options d
  left join public.question_options o on o.question_id = d.question_id and o.position = d.position
 where o.id is null
on conflict (id) do nothing;

update public.quiz_questions qq
   set position = s.question_number,
       points = s.points
  from _myp_mock_forward_stage s
 where qq.quiz_id = 'd4000000-0000-4000-8000-000000000001'::uuid
   and qq.question_id = s.question_id
   and (qq.position is distinct from s.question_number or qq.points is distinct from s.points);

update public.question_hints h
   set body = d.body,
       body_doc = null,
       status = 'published',
       source = 'manual',
       approved_by = coalesce(h.approved_by, '3c3ed712-f409-4aa1-a645-816418e22ec4'::uuid),
       approved_at = coalesce(h.approved_at, now()),
       published_at = coalesce(h.published_at, now())
  from _myp_mock_forward_hints d
 where h.exam_id = 'd4000000-0000-4000-8000-000000000002'::uuid
   and h.question_id = d.question_id
   and h.level = d.level
   and (
     h.body is distinct from d.body
     or h.body_doc is not null
     or h.status is distinct from 'published'
     or h.source is distinct from 'manual'
     or h.approved_by is null
     or h.approved_at is null
     or h.published_at is null
   );

insert into public.question_hints
  (id, organization_id, exam_id, question_id, level, body, body_doc, status, source,
   created_by, approved_by, approved_at, published_at)
select d.hint_id, '0a400000-0000-4000-8000-000000000001'::uuid, 'd4000000-0000-4000-8000-000000000002'::uuid, d.question_id, d.level, d.body, null,
       'published', 'manual', '3c3ed712-f409-4aa1-a645-816418e22ec4'::uuid, '3c3ed712-f409-4aa1-a645-816418e22ec4'::uuid, now(), now()
  from _myp_mock_forward_hints d
  left join public.question_hints h
    on h.exam_id = 'd4000000-0000-4000-8000-000000000002'::uuid and h.question_id = d.question_id and h.level = d.level
 where h.id is null
on conflict do nothing;

update public.quizzes q
   set title = 'MYP4 Mathematics — Mock Examination',
       description = 'Grade 9 · MYP 4 · Mathematics · Mock Examination. Classification of data, measures of central tendency, stem-and-leaf diagrams, five-number summaries and box plots, grouped frequency tables, estimated mean, histograms with frequency density, cumulative frequency curves, line graphs and standard deviation. 45 questions, 221 marks: Section A (objective) and Section B (structured statistical investigations).',
       settings = coalesce(q.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","total_marks":221,"source":"myp-mock-myp4-mock","mock_exam_key":"myp4-mock","mock_code":"MYP4-MOCK-2026","duration_minutes":150,"sections":[{"id":"A","title":"Section A — Objective","questions":22,"marks":62,"instructions":"One correct answer per question. The options are written so a wrong choice identifies a specific misconception."},{"id":"B","title":"Section B — Structured","questions":23,"marks":159,"instructions":"Show your working. Every part carries its own marks, its own answer box and its own two hints."}]}'::jsonb
 where q.id = 'd4000000-0000-4000-8000-000000000001'::uuid
   and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   and (
     q.title is distinct from 'MYP4 Mathematics — Mock Examination'
     or q.description is distinct from 'Grade 9 · MYP 4 · Mathematics · Mock Examination. Classification of data, measures of central tendency, stem-and-leaf diagrams, five-number summaries and box plots, grouped frequency tables, estimated mean, histograms with frequency density, cumulative frequency curves, line graphs and standard deviation. 45 questions, 221 marks: Section A (objective) and Section B (structured statistical investigations).'
     or q.settings is distinct from (coalesce(q.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","total_marks":221,"source":"myp-mock-myp4-mock","mock_exam_key":"myp4-mock","mock_code":"MYP4-MOCK-2026","duration_minutes":150,"sections":[{"id":"A","title":"Section A — Objective","questions":22,"marks":62,"instructions":"One correct answer per question. The options are written so a wrong choice identifies a specific misconception."},{"id":"B","title":"Section B — Structured","questions":23,"marks":159,"instructions":"Show your working. Every part carries its own marks, its own answer box and its own two hints."}]}'::jsonb)
   );

update public.exams e
   set title = 'MYP4 Mathematics — Mock Examination',
       description = 'Grade 9 · MYP 4 · Mathematics · Mock Examination. Classification of data, measures of central tendency, stem-and-leaf diagrams, five-number summaries and box plots, grouped frequency tables, estimated mean, histograms with frequency density, cumulative frequency curves, line graphs and standard deviation. 45 questions, 221 marks: Section A (objective) and Section B (structured statistical investigations).',
       instructions = 'MYP4 MATHEMATICS — MOCK EXAMINATION (Grade 9)

Time allowed: 2 hours 30 minutes.

SECTION A — Objective questions (questions 1–22).
Each question has one correct answer (or, where stated, more than one). Several questions give you a data set you must interrogate before you can choose: read the question twice.

SECTION B — Structured questions (questions 23–45).
Show your working. Marks are printed beside every part. Where a question asks you to CONSTRUCT a table, histogram, cumulative frequency curve or box plot, build it in the workspace — you are not given a completed one, because constructing the representation is what is being assessed.

EXAMINATION OBJECTIVES. By the end of this paper you should be able to: classify data as qualitative or quantitative, discrete or continuous, and justify the classification; choose and justify an appropriate measure of central tendency, including in the presence of outliers; construct and interpret stem-and-leaf diagrams, grouped frequency tables, histograms with unequal class widths, cumulative frequency curves and box plots; estimate a mean from grouped data using midpoints; calculate and interpret standard deviation; and compare distributions with evidence rather than impression.

GENERAL INSTRUCTIONS.
1. A calculator is permitted in Section B and for the standard deviation questions, but write down the formula or method you use. Standard deviation is the population standard deviation σ = √(Σ(x − x̄)² / n) unless a question says otherwise.
2. Give units, and round to the accuracy stated in each part. If no accuracy is stated, give 3 significant figures.
3. A hint is available on every part. Hints guide the method and never give the answer; using one costs no marks and is recorded only to support your revision.
4. Your answers save automatically; after a disconnection, reopen the paper and your work is restored.
5. Quartiles use the median-excluded method: for an odd number of values the median is not used in either half.

MARKS. Every part shows its marks. Section A is worth 62 marks and Section B 159 marks, out of a total of 221. Pass mark: your institution''s configured threshold (default 50%).',
       duration_minutes = 150,
       settings = coalesce(e.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","total_marks":221,"source":"myp-mock-myp4-mock","mock_exam_key":"myp4-mock","mock_code":"MYP4-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb
 where e.id = 'd4000000-0000-4000-8000-000000000002'::uuid
   and e.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   and (
     e.title is distinct from 'MYP4 Mathematics — Mock Examination'
     or e.description is distinct from 'Grade 9 · MYP 4 · Mathematics · Mock Examination. Classification of data, measures of central tendency, stem-and-leaf diagrams, five-number summaries and box plots, grouped frequency tables, estimated mean, histograms with frequency density, cumulative frequency curves, line graphs and standard deviation. 45 questions, 221 marks: Section A (objective) and Section B (structured statistical investigations).'
     or e.instructions is distinct from 'MYP4 MATHEMATICS — MOCK EXAMINATION (Grade 9)

Time allowed: 2 hours 30 minutes.

SECTION A — Objective questions (questions 1–22).
Each question has one correct answer (or, where stated, more than one). Several questions give you a data set you must interrogate before you can choose: read the question twice.

SECTION B — Structured questions (questions 23–45).
Show your working. Marks are printed beside every part. Where a question asks you to CONSTRUCT a table, histogram, cumulative frequency curve or box plot, build it in the workspace — you are not given a completed one, because constructing the representation is what is being assessed.

EXAMINATION OBJECTIVES. By the end of this paper you should be able to: classify data as qualitative or quantitative, discrete or continuous, and justify the classification; choose and justify an appropriate measure of central tendency, including in the presence of outliers; construct and interpret stem-and-leaf diagrams, grouped frequency tables, histograms with unequal class widths, cumulative frequency curves and box plots; estimate a mean from grouped data using midpoints; calculate and interpret standard deviation; and compare distributions with evidence rather than impression.

GENERAL INSTRUCTIONS.
1. A calculator is permitted in Section B and for the standard deviation questions, but write down the formula or method you use. Standard deviation is the population standard deviation σ = √(Σ(x − x̄)² / n) unless a question says otherwise.
2. Give units, and round to the accuracy stated in each part. If no accuracy is stated, give 3 significant figures.
3. A hint is available on every part. Hints guide the method and never give the answer; using one costs no marks and is recorded only to support your revision.
4. Your answers save automatically; after a disconnection, reopen the paper and your work is restored.
5. Quartiles use the median-excluded method: for an odd number of values the median is not used in either half.

MARKS. Every part shows its marks. Section A is worth 62 marks and Section B 159 marks, out of a total of 221. Pass mark: your institution''s configured threshold (default 50%).'
     or e.duration_minutes is distinct from 150
     or e.settings is distinct from (coalesce(e.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","total_marks":221,"source":"myp-mock-myp4-mock","mock_exam_key":"myp4-mock","mock_code":"MYP4-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb)
   );

do $$
declare
  v_questions integer;
  v_options integer;
  v_paper_rows integer;
  v_hints integer;
begin
  select count(*) into v_questions
    from _myp_mock_forward_stage s
    join public.questions q on q.id = s.question_id
   where q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
     and q.type = s.question_type
     and q.prompt = s.prompt
     and q.prompt_doc = s.prompt_doc
     and q.explanation = s.explanation
     and q.explanation_doc is null
     and q.points = s.points
     and q.difficulty = s.difficulty
     and q.topic = s.topic
     and q.subtopic = s.subtopic
     and q.config = s.config;
  if v_questions <> 45 then
    raise exception 'MYP4-MOCK-2026: only % question rows match the authored forward payload after update', v_questions;
  end if;

  select count(*) into v_options
    from _myp_mock_forward_options d
    join public.question_options o
      on o.question_id = d.question_id and o.position = d.position
   where o.label = d.label and o.is_correct = d.is_correct and o.content_doc is null;
  if v_options <> (select count(*) from _myp_mock_forward_options) then
    raise exception 'MYP4-MOCK-2026: option rows did not reconcile to the authored payload';
  end if;

  select count(*) into v_paper_rows
    from _myp_mock_forward_stage s
    join public.quiz_questions qq
      on qq.quiz_id = 'd4000000-0000-4000-8000-000000000001'::uuid and qq.question_id = s.question_id
   where qq.position = s.question_number and qq.points = s.points;
  if v_paper_rows <> 45 then
    raise exception 'MYP4-MOCK-2026: only % quiz-question rows match the authored order and marks', v_paper_rows;
  end if;

  select count(*) into v_hints
    from _myp_mock_forward_hints d
    join public.question_hints h
      on h.exam_id = 'd4000000-0000-4000-8000-000000000002'::uuid and h.question_id = d.question_id and h.level = d.level
   where h.body = d.body and h.status = 'published';
  if v_hints <> (select count(*) from _myp_mock_forward_hints) then
    raise exception 'MYP4-MOCK-2026: only % authored hint rows were reconciled', v_hints;
  end if;

  if not exists (
    select 1 from public.quizzes q
     where q.id = 'd4000000-0000-4000-8000-000000000001'::uuid and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and q.settings @> '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","total_marks":221,"source":"myp-mock-myp4-mock","mock_exam_key":"myp4-mock","mock_code":"MYP4-MOCK-2026","duration_minutes":150,"sections":[{"id":"A","title":"Section A — Objective","questions":22,"marks":62,"instructions":"One correct answer per question. The options are written so a wrong choice identifies a specific misconception."},{"id":"B","title":"Section B — Structured","questions":23,"marks":159,"instructions":"Show your working. Every part carries its own marks, its own answer box and its own two hints."}]}'::jsonb
  ) then
    raise exception 'MYP4-MOCK-2026: quiz metadata did not reconcile';
  end if;
  if not exists (
    select 1 from public.exams e
     where e.id = 'd4000000-0000-4000-8000-000000000002'::uuid and e.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and e.duration_minutes = 150
       and e.settings @> '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","total_marks":221,"source":"myp-mock-myp4-mock","mock_exam_key":"myp4-mock","mock_code":"MYP4-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb
  ) then
    raise exception 'MYP4-MOCK-2026: examination metadata did not reconcile';
  end if;
end $$;

commit;
